import { Round } from "../../../store/classes/rounds/Rounds";
import { RoundTypes } from "../../../common/enums/RoundTypes";
import { DelRoundButton } from "../../pages/game/DelRoundButton";
import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";

interface IRoundsMenu {
  listOfRounds: Round[];
  onPickRound: (round: Round) => void;
  onAddRound: () => void;
  children: any;
  showDelButton: boolean;
}
export const RoundsMenu = observer(
  ({
    listOfRounds,
    onPickRound,
    onAddRound,
    children,
    showDelButton,
  }: IRoundsMenu) => {
    let roundTypesCounter: {
      [roundType: string]: number;
    } = {};
    Object.values(RoundTypes).forEach((key) => {
      roundTypesCounter[key] = 0;
    });
    const { settings } = useStore();
    const getRoundCLass = (roundId: string) => {
      let def = "btn btn-secondary round-element round-container";
      return (
        def + (settings.pickedRoundId === roundId ? " selected-round " : "")
      );
    };
    return (
      <div className="d-flex justify-content-between mt-2 mb-9 mw-100 overflow-y-hidden">
        <div className="d-flex justify-content-center">
          {listOfRounds.map((round, index) => {
            roundTypesCounter[round.data.type]++;
            return (
              <button
                key={round.data.id + "_" + settings.pickedRoundId}
                className={getRoundCLass(round.data.id)}
                onClick={(e) => onPickRound(round)}
              >
                <span className="round-container-title">
                  {round.data.title}
                </span>
                {showDelButton && (
                  <DelRoundButton roundId={round.data.id}></DelRoundButton>
                )}
              </button>
            );
          })}
          {children}
        </div>
      </div>
    );
  }
);
