import { BasePage } from "../../BasePage";
import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { ServerMessagesArea } from "../../../enums/ServerMessagesArea";
import { useNavigate } from "react-router";
import { setAuthParams } from "../../../store/utils";
import { COOKIE_EXP_DAYS } from "../../../env";

export const MailAuthPage = observer(() => {
  const { userRegGl, messagesGl } = useStore();
  const changeUserAuthParam = (e) => {
    userRegGl[e.target.name] = e.target.value;
  };
  const navigate = useNavigate();
  const sendForm = async (e) => {
    e.preventDefault();
    const authResp = await userRegGl.emailAuth();
    if (authResp.data.status == 2) {
      await messagesGl.add(
        {
          className: "alert-warning",
          text: authResp.data.msg,
          area: ServerMessagesArea.page,
        },
        5000
      );
    } else {
      setAuthParams(
        authResp.data.refreshToken,
        authResp.data.expTime,
        COOKIE_EXP_DAYS
      );
      // await queryService.getMailToken();
      await navigate("/list");
    }
  };
  return (
    <BasePage>
      <div className="container h-100 justify-content-center align-items-center">
        <div className="row justify-content-center align-items-center">
          <div className="col-md-12 col-lg-6 mt-8">
            <form
              action=""
              className=" bg-white p-7"
              style={{ borderRadius: 20 + "px" }}
              onSubmit={sendForm}
            >
              <div className="row mb-2 justify-content-center">
                <label
                  htmlFor="authEmail"
                  className="form-label col-md-5 col-lg-4 d-flex align-items-center"
                  style={{ whiteSpace: "nowrap" }}
                >
                  Введите почту
                </label>
                <div className="col-md-7 col-lg-8">
                  <input
                    required
                    name="authEmail"
                    onChange={changeUserAuthParam}
                    value={userRegGl.authEmail}
                    type="text"
                    id="authEmail"
                    className="form-control"
                  />
                </div>
              </div>
              <div className="row mb-2 justify-content-center">
                <label
                  htmlFor="authPassword"
                  className="form-label col-md-5 col-lg-4 d-flex align-items-center"
                  style={{ whiteSpace: "nowrap" }}
                >
                  Введите пароль
                </label>
                <div className="col-md-7 col-lg-8">
                  <input
                    name="authPassword"
                    required
                    onChange={changeUserAuthParam}
                    value={userRegGl.authPassword}
                    type="password"
                    id="authPassword"
                    className="form-control"
                  />
                </div>
              </div>
              <div className="d-flex justify-content-end">
                <button className="btn btn-success">Авторизация</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </BasePage>
  );
});
