import { BasePage } from "../BasePage";
import { serverUrl } from "../../env";
import { useEffect } from "react";
import { useWindowSize } from "../../hooks/hooks";
import { Header } from "../Header";

export const TgAuthPage = () => {
  const width = useWindowSize();

  useEffect(() => {
    const externalScript = document.createElement("script");
    externalScript.src = "https://telegram.org/js/telegram-widget.js?22";
    externalScript.setAttribute("data-telegram-login", "mafiaPuzzles_bot");
    externalScript.setAttribute("data-size", "large");
    externalScript.setAttribute(
      "data-auth-url",
      serverUrl + "/telegramRegistration"
    );
    externalScript.setAttribute("data-request-access", "write");

    externalScript.async = true;
    document.getElementById("tg_wrap").append(externalScript);
    return () => {
      externalScript.remove();
    };
  }, []);
  return (
    <div>
      <Header key={width} />
      <div
        id="tg_wrap"
        className="d-flex justify-content-center align-items-center"
        style={{ height: 100 + "vh" }}
      ></div>
    </div>
  );
};
