import { HardLevelPicker } from "../question/HardLevelPicker";
import { useState } from "react";

interface IHardLevelForm {
  initRangeValue: number;
  onValChange: (newVal: number) => any;
}
export const HardLevelForm = ({
  initRangeValue,
  onValChange,
}: IHardLevelForm) => {
  const [rangeValue, setRangeValue] = useState(initRangeValue);

  const onRangeChange = (newVal: number) => {
    setRangeValue(newVal);
    onValChange(newVal);
  };
  return (
    <div className="form-group">
      <HardLevelPicker startValue={rangeValue} onValueChange={onRangeChange} />
      <div style={{ height: 50 + "px" }}>
        {rangeValue == 1 && (
          <span>
            Самые простые задачи, для людей которые только выучили правила.
          </span>
        )}
        {rangeValue == 2 && (
          <span>
            Сложнее чем предыдущие. Дле тех, кто уже ориентируется в правилах.
          </span>
        )}
        {rangeValue == 3 && (
          <span>Средние задачи, для тех кто уже играет пару месяцев.</span>
        )}
        {rangeValue == 4 && (
          <span>
            Для опытных игроков, которые могут держать в голове множество
            комбинаций.
          </span>
        )}
        {rangeValue == 5 && (
          <span>Самые сложные задачи для самых опытных игроков.</span>
        )}
      </div>
      <hr />
    </div>
  );
};
