import { MultiSelect } from "react-multi-select-component";
import React, { useState } from "react";
import PlayersOpinionMultiSelect, {
  IMultiSelectOption,
} from "./opinion/PlayersOpinionMultiSelect";
import { useStore } from "../../store/store";
import { Player } from "../../store/classes/players/Players";
import { observer } from "mobx-react-lite";

interface ILifeSelect {
  roundId: string;
}
export const LifeSelect = observer(({ roundId }: ILifeSelect) => {
  const { settings, playersOpinionGl, players } = useStore();
  const [listOfPlayers, setListOfPlayers]: [Player[], Function] = useState(
    players.getPlayersByRoundId(roundId)
  );
  const onSelectChange = (listOfSelected: IMultiSelectOption[]) => {
    let currentRoundPlayers = players.getPlayersByRoundId(roundId);
    currentRoundPlayers.map((el) => {
      el.alive = false;
    });
    listOfSelected.map((el) => {
      let tempPlayer = currentRoundPlayers.find((pl) => pl.id == el.value);
      if (tempPlayer) tempPlayer.alive = true;
    });
  };
  const toMultiSelectOptions = (player: Player) => {
    return {
      label: "Игрок №" + (player.numberValue + 1),
      value: player.id,
    };
  };
  return (
    <div className="form-group mb-3">
      <label htmlFor="pickedPlayer">Выберите отсавшихся игроков</label>
      <PlayersOpinionMultiSelect
        listOfOptions={listOfPlayers.map(toMultiSelectOptions)}
        onChangeProp={onSelectChange}
        listOfSelectOptions={listOfPlayers
          .filter((el) => el.alive)
          .map(toMultiSelectOptions)}
      />
    </div>
  );
});
