import { createContext, useContext } from "react";
import { Games, games } from "./classes/games/Games";
import { Rounds, rounds } from "./classes/rounds/Rounds";
import { Players, players } from "./classes/players/Players";
import { gameSettings, TempSettings } from "./classes/temp/TempSettings";
import {
  PlayersOpinion,
  playersOpinion,
} from "./classes/playersOpinion/PlayersOpinion";
import { IStoreObject } from "./interfaces/IStoreObject";
import { initData } from "./classes/mockData/initData";
import { Questions, questions } from "./classes/questions/Questions";
import { Messages, messages } from "./classes/messages/Messages";
import { Answers, answers } from "./classes/answers/Answers";
import {
  userReg,
  UserRegistration,
} from "./classes/userRegistration/UserRegistration";

const store: {
  games: Games;
  rounds: Rounds;
  players: Players;
  settings: TempSettings;
  playersOpinionGl: PlayersOpinion;
  answersGl: Questions;
  messagesGl: Messages;
  userAnswers: Answers;
  userRegGl: UserRegistration;
} = {
  games: games as Games,
  rounds: rounds as Rounds,
  players: players as Players,
  settings: gameSettings as TempSettings,
  playersOpinionGl: playersOpinion as PlayersOpinion,
  answersGl: questions as Questions,
  messagesGl: messages as Messages,
  userAnswers: answers as Answers,
  userRegGl: userReg as UserRegistration,
};

export const globalInit = () => {
  Object.keys(store)
    .filter((key) => key !== "settings")
    .forEach((key) => {
      global(store[key], key);
    });
};
const global = (obj: IStoreObject<any>, dataKey: string) => {
  obj.init(initData[dataKey]);
};
// globalInit();
// gameSettings.init(800);

export const StoreContext = createContext(store);

export const useStore = () => {
  return useContext<typeof store>(StoreContext);
};

export default store;
