import { BasePage } from "../../BasePage";
import React, { useEffect } from "react";
import { useStore } from "../../../store/store";
import { Link } from "react-router-dom";
import { gameSettings } from "../../../store/classes/temp/TempSettings";
import { observer } from "mobx-react-lite";
import { SmallGameField } from "./SmallGameField";
import InfiniteScroll from "react-infinite-scroll-component";
import { GameManagementPanel } from "../myGames/GameManagementPanel";
import { IPagination } from "../../../common/interfaces/pagination/IPagination";
import { useNavigate } from "react-router";

export interface IListOfGames {
  loadGames: (pagination: IPagination) => Promise<IPagination>;
  showManagementPanel: boolean;
}
export const ListOfGames = observer(
  ({ loadGames, showManagementPanel = false }: IListOfGames) => {
    const { games, settings, rounds, players, playersOpinionGl } = useStore();
    const nav = useNavigate();
    useEffect(() => {
      gameSettings.init(300);
    });
    const loadWrapper = async () => {
      // alert("вызываю");
      const t = await loadGames(settings.pagination);
      settings.pagination = { ...t };
    };

    useEffect(() => {
      settings.initPagination();
      settings.pickedSettingPlayer = "";
      loadWrapper();
    }, []);
    return (
      <BasePage>
        <div key={settings.pagination.currentPage}>
          <InfiniteScroll
            next={loadWrapper}
            hasMore={settings.pagination.hasMore}
            loader={<p>...loading</p>}
            dataLength={games.dataAr.length}
          >
            <div className="list-of-game">
              {games.dataAr.map((el) => {
                console.log("Играа!!!");
                console.log(el);
                return (
                  <>
                    <div key={el.myID} className="list-of-game-item ">
                      <Link to={`/games/${el.myID}`}>
                        <div className="card">
                          <div className="card-body">
                            <SmallGameField
                              key={el.myID}
                              className="ms-5 mt-5 mt-lg-5 ms-lg-5 ms-xl-11 ms-xxl-11 ms-md-5"
                              roundId={
                                rounds.getRoundsByGameId(el.myID)[0].data.id
                              }
                              style={{
                                position: "relative",
                                height: 230 + "px",
                                width: 50 + "%",
                              }}
                            />

                            {!showManagementPanel && (
                              <div className="d-flex justify-content-center mt-2">
                                <Link
                                  to={`/games/${el.myID}`}
                                  className="card-text"
                                >
                                  <button className="btn btn-warning">
                                    Перейти
                                  </button>
                                </Link>
                              </div>
                            )}
                            <div className="mt-2">
                              {showManagementPanel && (
                                <GameManagementPanel key={el.myID} game={el} />
                              )}
                            </div>
                          </div>
                        </div>
                      </Link>
                    </div>
                  </>
                );
              })}
            </div>
          </InfiniteScroll>
        </div>
      </BasePage>
    );
  }
);
