import { useLocation, useNavigate } from "react-router";
import { queryService } from "../../services/Query";
import { ReactNode, useLayoutEffect, useState } from "react";
import { TokenCheckStatus } from "../../enums/TokenCheckStatus";

export interface IProtectedRoute {
  children: ReactNode;
  redirectPath?: string;
  // key?: any;
  //   name:string
}

let checkTokenStatus: TokenCheckStatus = TokenCheckStatus.sleep;

export const ProtectedRoute = ({ children, redirectPath = "/tgAuth" }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isAccessCheckFinished, setIsAccessCheckFinished] = useState(false);

  const checkAccessToken = async () => {
    try {
      await queryService.getAccessToken();
      setIsAccessCheckFinished(true);
    } catch (e) {
      console.log(e);
      navigate(redirectPath);
    }
  };
  const checkWrapper = async () => {
    if (checkTokenStatus === TokenCheckStatus.sleep) {
      checkTokenStatus = TokenCheckStatus.inProcess;
      await checkAccessToken();
      checkTokenStatus = TokenCheckStatus.sleep;
    }
  };

  useLayoutEffect(() => {
    checkWrapper();
  }, []);
  return <>{isAccessCheckFinished && children}</>;
};
