import PlayersOpinionMultiSelect, {
  IMultiSelectOption,
} from "../opinion/PlayersOpinionMultiSelect";
import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";
import React from "react";
import { useStore } from "../../../store/store";
import { onMultiSelectWrap, uuidv4 } from "../../../store/utils";
import { AddComment } from "../comment/AddComment";
import { LifeSelect } from "../LifeSelect";

interface IVotePanel {
  playerId: string;
  pickedRoundId: string;
}
export const VotePanel = ({ playerId, pickedRoundId }: IVotePanel) => {
  const { settings, playersOpinionGl, players } = useStore();

  const onMultiSelectChange = (
    listOfSelected: IMultiSelectOption[],
    playerId: string,
    positionType: PlayerPositions
  ) => {
    let listOfPlayerOpinionIds = playersOpinionGl.getByPlayerIdAndOpinionType(
      playerId,
      positionType
    );
    listOfSelected.forEach((el) => {
      delete listOfPlayerOpinionIds[el.value];
      playersOpinionGl.add({
        id: uuidv4(),
        player_id: playerId,
        opinionType: positionType,
        to: el.value,
      });
    });

    Object.values(listOfPlayerOpinionIds).forEach((playerOpinionId) => {
      playersOpinionGl.delete(playerOpinionId);
    });
  };

  return (
    <form>
      <div className="form-group mb-3">
        <label htmlFor="pickedPlayer">
          Выберите за кого проголосовал игрок
        </label>
        <PlayersOpinionMultiSelect
          key={playerId + "_" + PlayerPositions.vote}
          listOfOptions={players
            .getPlayersByRoundIdAndOpinion(
              pickedRoundId,
              PlayerPositions.vote,
              playerId
            )
            .map((el) => {
              return {
                label: el.text,
                value: el.id,
              };
            })}
          listOfSelectOptions={playersOpinionGl
            .getOpinionByPlayerId(playerId)
            .filter((el) => el.opinionType === PlayerPositions.vote)
            .map((el) => {
              return {
                label: el.numberValue,
                value: el.to,
              };
            })}
          onChangeProp={onMultiSelectWrap(
            playerId,
            PlayerPositions.vote,
            playersOpinionGl
          )}
        ></PlayersOpinionMultiSelect>
        <LifeSelect roundId={pickedRoundId} />
      </div>
      <div className="mt-2">
        <AddComment roundId={pickedRoundId} />
      </div>
    </form>
  );
};
