import { useState } from "react";
import { observer } from "mobx-react-lite";
import { useStore } from "../../../store/store";

export interface IAddComment {
  roundId: string;
}
export const AddComment = observer(({ roundId }: IAddComment) => {
  const { rounds } = useStore();
  const [localComment, setLocalComment] = useState(
    rounds.data[roundId].data.comment
  );
  const onChange = (e) => {
    setLocalComment(e.target.value);
    rounds.data[roundId].data.comment = e.target.value;
  };
  return (
    <div>
      <textarea
        onChange={onChange}
        value={localComment}
        className="form-control"
        rows={4}
        cols={40}
        placeholder="Напишите поясенение к раунду если необходимо"
      ></textarea>
    </div>
  );
});
