interface iGames {
  id: IGame;
}

export class Games implements IStoreObject<IGame> {
  public data: {
    [id: string]: Game;
  } = {};
  public gamePreview: IGamePreview[] = [];
  constructor() {
    makeAutoObservable(this);
    this.add = this.add.bind(this);
  }
  public async getListOfGames(urlSource, pag) {
    const res = await queryService.noGooglePostQuery(urlSource, {
      pagination: pag,
    });
    const gamesResp: IFullGameResp[] = res?.data?.games;
    const pagination: IPagination = res?.data?.pagination;
    if (gamesResp) {
      gamesResp.forEach((game) => {
        console.log("тут");
        console.log(game);
        this.addFullGame(game);
      });
      return pagination as IPagination;
    }
    return {} as IPagination;
  }
  add(game: any) {
    if (this.data[game.myID] === undefined) {
      this.data[game.myID] = new Game(game);
    } else {
      this.data[game.myID].all = game;
    }
  }
  async initGame(gameId: string) {
    if (!this.data[gameId]) {
      const gameResp = await queryService.noGooglePostQuery("/getGameById", {
        id: gameId,
      });
      await this.addFullGame(gameResp.data.game);
      return gameId;
    }
  }
  async initUserGame(gameId: string) {
    console.log(gameId)
    const gameResp = await queryService.noGooglePostQuery(
      "/getGameByIdForUser",
      {
        id: gameId,
      }
    );
    await this.addFullGame(gameResp.data.game);
    //
  }
  addFullGame(game: IFullGameResp) {
    console.log("ИГра!!!!");
    Object.values(game["rounds"]).forEach((round) => {
      games.add(game);
      rounds.add(round["roundInfo"]["data"]);

      if (game.questions) {
        Object.values(game?.questions).forEach((el) => {
          if (el.answer) {
            questions.add(el);
          } else {
            answers.add({
              questionId: el.id,
              finished: false,
              status: AnswerStatuses.start,
              data: [],
              questionText: el.question,
              gameId: game.myID,
            });
          }
        });
      }

      players.initAr(
        Object.keys(round.players).map((playerId) => {
          return round.players[playerId].playerInfo;
        })
      );
      Object.values(round["players"]).forEach((el) => {
        el["playerOpinion"].forEach((pOp) => {
          playersOpinion.add(pOp);
        });
      });
    });
  }
  addGamePreview(game: IGamePreview) {
    this.gamePreview.push(game);
  }

  async saveFullGame(gameId: string, isNewGame) {
    const finalJson = {};
    const gameJson = games.findById(gameId);
    finalJson[gameJson.myID] = {};
    finalJson[gameJson.myID] = gameJson;

    const questionJson = questions.onSave(gameId);
    finalJson[gameJson.myID]["questions"] = questionJson;

    const roundsJson = rounds.getRoundsByGameId(gameId);
    finalJson[gameJson.myID]["rounds"] = {};
    roundsJson.forEach((round) => {
      finalJson[gameJson.myID]["rounds"][round.data.id] = {};
      finalJson[gameJson.myID]["rounds"][round.data.id]["roundInfo"] = round;
      finalJson[gameJson.myID]["rounds"][round.data.id]["players"] = {};
    });

    let playersJson = [];
    roundsJson.forEach((r) => {
      playersJson = [...players.getPlayersByRoundId(r.data.id), ...playersJson];
    });
    console.log("Игроки - json!!!!");
    console.log(playersJson);

    playersJson.forEach((player) => {
      finalJson[gameJson.myID]["rounds"][player.roundId]["players"][player.id] =
        {};
      finalJson[gameJson.myID]["rounds"][player.roundId]["players"][player.id][
        "playerInfo"
      ] = player;
      finalJson[gameJson.myID]["rounds"][player.roundId]["players"][player.id][
        "playerOpinion"
      ] = playersOpinion.getOpinionByPlayerId(player.id);
    });

    console.log("json!!!!");
    console.log(finalJson);

    return await queryService.noGooglePostQuery("/save", {
      game: finalJson,
    });
  }
  get dataAr(): IGame[] {
    return (
      Object.keys(this.data)
        .filter((key) => !gameSettings.newGames[this.data[key].myID])
        .map((key) => this.data[key]) ?? []
    );
  }
  getRoundsByGameId(gameId: string) {
    return rounds.dataAr.filter((round) => {
      return round.data.gameId === gameId;
    });
  }
  createEmptyGame(): string {
    const createdGameId = uuidv4();
    const createdRoundId = uuidv4();

    const initGamesData: { [id: string]: any } = {
      [createdGameId]: {
        myID: createdGameId,
      },
    };
    this.add(initGamesData[createdGameId]);

    const initRoundsData: { [id: string]: IRoundInfo } = {
      [createdRoundId]: {
        title: "раунд 1",
        type: RoundTypes.day,
        gameId: createdGameId,
        id: createdRoundId,
        time: Date.now(),
        comment: "",
      },
    };
    rounds.add(initRoundsData[createdRoundId]);

    Object.keys(initRoundsData).forEach((roundKey) => {
      for (let i = 0; i < 10; i++) {
        let id = uuidv4();
        players.add({
          id,
          text: "Игрок " + (i + 1),
          roundId: roundKey,
          alive: true,
          numberValue: i,
          isSher: false,
          sherCheck: {},
        });
      }
    });

    const initPlayersData: { [id: string]: IPlayerInfo } = {};
    return createdGameId;
  }
  findById(id: string) {
    return this.data[id];
  }
  init(tempD) {
    Object.keys(tempD).forEach((key) => {
      this.add(tempD[key]);
    });
  }
  increaseNumberOfRoundsById(id: string) {
    this.data[id].increaseNumberOfRounds();
  }
  setRoundCounter() {}
  // increaseNumberOfRounds(id:string){
  //     this.data[id].
  // }
  setHardLevel(listOfGames: Game[], currentGameId: string, hardLevel: number) {
    listOfGames.find((el) => {
      return el.myID === currentGameId;
    });
  }
}

export class Game {
  get numberOfRounds(): number {
    return rounds.dataAr.filter((el) => {
      return el.data.gameId == this.myID;
    }).length;
  }

  set numberOfRounds(value: number) {
    this._numberOfRounds = value;
  }
  public myID: string;
  public title: string;
  public _id: string;
  private _numberOfRounds: number = 0;
  public hardLevel: number = 0;

  constructor(game: IGame) {
    this.myID = game.myID;
    this.hardLevel = game.hardLevel ?? 0;
    this._id = game._id;
    makeAutoObservable(this);
  }
  set all(game: IGame) {
    this.myID = game.myID;
  }
  increaseNumberOfRounds() {
    this._numberOfRounds++;
  }
}

