import React, { useEffect, useState } from "react";
import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { GameField } from "../../constructor/GameField";
import { RoundsMenu } from "../../constructor/rounds/RoundsMenu";
import { Round } from "../../../store/classes/rounds/Rounds";
import { RoundTypes } from "../../../common/enums/RoundTypes";
import { DayPanel } from "../../constructor/panels/DayPanel";
import { NightPanel } from "../../constructor/panels/NightPanel";
import { VotePanel } from "../../constructor/panels/VotePanel";
import { AnswerBlock } from "../../question/QuestionConfiguration";
import { RoundModal } from "../../constructor/round/RoundModal";
import { messages } from "../../../store/classes/messages/Messages";
import { ServerMessagesArea } from "../../../enums/ServerMessagesArea";
import { ResponseStatuses } from "../../../common/enums/responseStatuses";
import { IGame } from "../../../store/classes/games/IGame";
import { IFullGameResp } from "../../../interfaces/IFullGameResp";
import { IGameEntity } from "../../../common/interfaces/game/IGameEntity";

interface IMainGame {
  globalGameId: string;
  currentGame?: IGameEntity;
  isNewGame?: boolean;
}
export const MainGame = observer(
  ({ globalGameId, currentGame, isNewGame = false }: IMainGame) => {
    const { games, settings, playersOpinionGl, rounds, players } = useStore();

    const onPickRound = (round: Round) => {
      settings.pickedRoundId = round.data.id;
    };
    const [isModalShown, setIsModalShown] = useState(false);

    const onGameSave = async () => {
      if (isNewGame) {
        settings.newGames[settings.pickedGameId] = settings.pickedGameId;
      }
      const saveRes = await games.saveFullGame(
        settings.pickedGameId,
        isNewGame
      );
      if (saveRes.data.status == ResponseStatuses.ok) {
        messages.add({
          text: "Успешно сохранили!!",
          className: "alert alert-success",
          area: ServerMessagesArea.page,
        });
        if (isNewGame) {
          if (settings.newGames[settings.pickedGameId]) {
            delete settings.newGames[settings.pickedGameId];
          }
        }
      } else {
        console.log(saveRes);
        messages.add({
          text: saveRes.data.msg,
          className: "alert alert-danger",
          area: ServerMessagesArea.page,
        });
      }
    };
    // useEffect(() => {
    //   games.initGame(settings.pickedGameId);
    // }, []);
    const RenderSwitchPanel = ({
      cond,
      pickedPlayerId,
    }: {
      cond: RoundTypes;
      pickedPlayerId: string;
    }) => {
      if (!pickedPlayerId && cond !== RoundTypes.night) {
        return (
          <>
            <h3>Выберите игрока</h3>
          </>
        );
      }
      switch (cond) {
        case RoundTypes.day:
          return (
            <DayPanel
              playerId={settings.pickedPlayerId}
              pickedPlayerOpinion={settings.pickedPlayerOpinion}
              pickedRoundId={settings.pickedRoundId}
            />
          );
        case RoundTypes.night:
          return <NightPanel roundId={settings.pickedRoundId} />;
        case RoundTypes.vote:
          return (
            <VotePanel
              playerId={settings.pickedPlayerId}
              pickedRoundId={settings.pickedRoundId}
            />
          );
      }
    };
    return (
      <div className="container-fluid">
        <RoundsMenu
          listOfRounds={rounds.getRoundsByGameId(globalGameId)}
          onPickRound={onPickRound}
          onAddRound={() => setIsModalShown(true)}
          showDelButton={true}
        >
          <div className="d-flex justify-content-between">
            <div className="d-flex justify-content-center">
              <RoundModal />
              <AnswerBlock />
            </div>
            <button
              className="btn btn-success round-element round-container"
              onClick={onGameSave}
            >
              <span className="round-container-title">Сохранить все</span>
            </button>
          </div>
        </RoundsMenu>
        <div className="row justify-content-center">
          {settings.elementRadius && settings.pickedRoundId && (
            <>
              <GameField
                style={{ position: "relative", height: "100vh", width: "50%" }}
                roundId={settings.pickedRoundId}
              />
            </>
          )}
          <div className="col-md-4">
            {settings.pickedRoundId && (
              <RenderSwitchPanel
                key={settings.pickedPlayerId}
                pickedPlayerId={settings.pickedPlayerId}
                cond={rounds.data[settings.pickedRoundId].data.type}
              />
            )}
            {!settings.pickedRoundId && <h3>Выберите раунд</h3>}
          </div>
        </div>
      </div>
    );
  }
);
