import { PlayerPositions } from "../common/enums/PlayerPositionTypes";
import { IMultiSelectOption } from "../components/constructor/opinion/PlayersOpinionMultiSelect";
import { setCookie } from "typescript-cookie/dist/built/src";
import { queryService } from "../services/Query";
import { Cookies } from "typescript-cookie";

export function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    var r = (Math.random() * 16) | 0,
      v = c == "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}
export const setHelper = (setF: Function, e: any) => {
  setF((prev) => test(prev));
  // setF((prev) => {
  //   prev[e] = e.target.value;
  //   return { ...prev };
  // });
  function test(prev: any) {
    prev[e.target.name] = e.target.value;
    return { ...prev };
  }
};

export const setAuthParams = (
  refreshToken: string,
  tokenExpSec: number,
  expDays: number
) => {
  queryService.refreshToken = refreshToken;
  queryService.accessTokenExtTime = tokenExpSec;
  Cookies.set("refreshToken", refreshToken, {
    expires: expDays,
  });
};

export const arToMultiSelect = (
  item: {}[],
  valueKey,
  labelKey
): IMultiSelectOption[] => {
  return item.map((el) => {
    return {
      value: el[valueKey],
      label: el[labelKey],
    };
  });
};

export const onMultiSelectChange = (
  listOfSelected: IMultiSelectOption[],
  playerId: string,
  positionType: PlayerPositions,
  source: {
    getByPlayerIdAndOpinionType: (
      playerId: string,
      positionType: PlayerPositions
    ) => { [id: string]: string };
    add: ({
      id,
      player_id,
      opinionType,
      to,
    }: {
      id: string;
      player_id: string;
      opinionType: PlayerPositions;
      to: string;
    }) => any;
    delete: (id: string) => any;
  }
) => {
  let listOfPlayerOpinionIds = source.getByPlayerIdAndOpinionType(
    playerId,
    positionType
  );
  listOfSelected.forEach((el) => {
    delete listOfPlayerOpinionIds[el.value];
    source.add({
      id: uuidv4(),
      player_id: playerId,
      opinionType: positionType,
      to: el.value,
    });
  });

  Object.values(listOfPlayerOpinionIds).forEach((playerOpinionId) => {
    source.delete(playerOpinionId);
  });
};

export const onMultiSelectWrap = (
  playerId: string,
  playersPosition: PlayerPositions,
  source
) => {
  return (listOfSelected: IMultiSelectOption[]) => {
    return onMultiSelectChange(
      listOfSelected,
      playerId,
      playersPosition,
      source
    );
  };
};
