import React, { useEffect, useState } from "react";
import { useStore } from "../../store/store";
import { observer } from "mobx-react-lite";
import { Player } from "../../store/classes/players/Players";

interface IRoundC {
  parentWidth: number;
  parentHeight?: number;
  key?: any;
  style?: any;
}

export const PlayingField = observer(
  ({
    children,
    roundId,
    style,
    onPickPlayer,
    className = "",
  }: {
    children: any;
    roundId: string;
    style?: any;
    onPickPlayer?: (numberValue: string) => any;
    className: string;
  }) => {
    const { settings, rounds, players } = useStore();

    const pickPlayer = (playerValue) => {
      if (!onPickPlayer) return;
      onPickPlayer(playerValue);
    };

    const [currentPlayers] = useState(players.getPlayersByRoundId(roundId));

    return (
      <div style={{ ...style }} className={className}>
        {currentPlayers?.length &&
          settings.playerSettingsAr.map((player, index, ar) => {
            const currentRoundPlayer = players
              .getPlayersByRoundId(roundId)
              .find((p) => p.numberValue == player.value);
            let design = {
              style: {
                top: player.top + "px",
                left: player.left + "px",
              },
            };
            return (
              // <div>
              //   {player.value == settings.pickedSettingPlayer + "f"}
              <GameElement
                key={player.value}
                onClick={() => pickPlayer(player.value)}
                id={player.value}
                style={design.style}
                currentRoundPlayer={currentRoundPlayer}
                width={settings.elementRadius * settings.radiusGrow}
                height={settings.elementRadius * settings.radiusGrow}
                className={"game-wrapper-el "}
              />
              // </div>
            );
          })}
        {children}
      </div>
    );
  }
);

interface IGameElement {
  id: number;
  style: {
    top: string;
    left: string;
  };
  className: string;
  width: number;
  height: number;
  onClick: () => any;
  key: any;
  currentRoundPlayer: Player;
}

const GameElement = observer(
  ({
    id,
    style,
    onClick,
    width,
    height,
    className,
    currentRoundPlayer,
  }: IGameElement) => {
    const { settings, rounds, players } = useStore();

    const KilledView = () => {
      const fontSize = Math.round(width / 2);
      return (
        <div
          style={{
            fontSize: Math.round(fontSize * 2.047) + "px",
            marginLeft: Math.round(fontSize * -1) + "px",
            marginTop: Math.round(fontSize * -0.595) + "px",
            position: "absolute",
            display: "inline-block",
          }}
        >
          X
        </div>
      );
    };
    const getSherClass = () => {
      return currentRoundPlayer?.isSher ? " is-sher " : " ";
    };
    return (
      <>
        <div
          onClick={onClick}
          className={
            "game-wrapper-el " +
            getSherClass() +
            (currentRoundPlayer?.numberValue === settings.pickedSettingPlayer
              ? " picked-player "
              : "")
          }
          style={{
            ...style,
            width: width + "px",
            height: height + "px",
            textAlign: "center",
            fontSize: Math.round(width / 2) + "px",
          }}
        >
          {id + 1}
          {!currentRoundPlayer?.alive && <KilledView />}
        </div>
      </>
    );
  }
);
