import React from "react";
import { useStore } from "../../../store/store";

interface IDelButton {
  roundId: string;
}
export const DelRoundButton = ({ roundId }: IDelButton) => {
  const { rounds } = useStore();
  const onDeleteRound = (e, roundId: string) => {
    e.stopPropagation();
    rounds.delete(roundId);
  };
  return (
    <span
      className="btn btn-danger round-container-del"
      onClick={(e) => onDeleteRound(e, roundId)}
    >
      x
    </span>
  );
};
export const delRoundWrapper = (roundId: string) => {
  return () => {
    return <DelRoundButton roundId={roundId} />;
  };
};
