import { observer } from "mobx-react-lite";
import { PlayingField } from "./PlayingField";
import React, { useEffect } from "react";
import { useStore } from "../../store/store";
import { ListOfConnections } from "../ListOfConnections";
import { set } from "mobx";

interface IGameField {
  roundId: string;
  style?: any;
  key?: string;
}
export const GameField = observer(({ roundId, style }: IGameField) => {
  const { settings, playersOpinionGl, players, rounds } = useStore();
  const pickPlayer = (playerValue) => {
    let player = players
      .getPlayersByRoundId(settings.pickedRoundId)
      .find((p) => {
        return p.numberValue == playerValue;
      });
    if (settings.pickedPlayerId === player.id) {
      settings.pickedPlayerId = "";
      settings.pickedSettingPlayer = "";
    } else {
      settings.pickedPlayerId = player.id;
      settings.pickedSettingPlayer = playerValue;
    }
  };
  return (
    <div
      style={{
        display: "inline-block",
        width: 52 + "%",
        height: settings.screenGameHeight + "vh",
        minHeight: 30 + "vh",
        position: "relative",
      }}
    >
      <PlayingField
        className=""
        style={style}
        roundId={roundId}
        onPickPlayer={pickPlayer}
      >
        {roundId && <ListOfConnections roundId={roundId} />}
      </PlayingField>
    </div>
  );
});
