import { PlayingField } from "./constructor/PlayingField";
import { NewConnections } from "./constructor/NewConnections";
import React from "react";
import { useStore } from "../store/store";
import { observer } from "mobx-react-lite";

interface IListOfConnections {
  roundId: string;
}

export const ListOfConnections = observer(({ roundId }: IListOfConnections) => {
  const { settings, players, playersOpinionGl } = useStore();
  return (
    <>
      {players.getPlayersByRoundId(roundId).map((player) => {
        return (
          <>
            {playersOpinionGl
              .getOpinionByPlayerId(player.id)
              .map((playerOpinion) => {
                return (
                  <NewConnections
                    player={
                      settings.playerSettings[
                        players.data[playerOpinion.player_id].numberValue
                      ]
                    }
                    positionType={playerOpinion.opinionType}
                    to={
                      settings.playerSettings[
                        players.data[playerOpinion.to].numberValue
                      ]
                    }
                    elementRadius={settings.elementRadius}
                    radiusGrow={settings.radiusGrow}
                  ></NewConnections>
                );
              })}
          </>
        );
      })}
    </>
  );
});
