import React, { useState } from "react";
import { MultiSelect } from "react-multi-select-component";
import { observer } from "mobx-react-lite";

//label:Игрок№1;value:его id
export interface IMultiSelectOption {
  label: string;
  value: string;
}

interface IPlayerOpinionMultiSelect {
  listOfOptions: IMultiSelectOption[];
  onChangeProp: (listOfSelected: IMultiSelectOption[]) => void;
  listOfSelectOptions: IMultiSelectOption[];
}
const PlayersOpinionMultiSelect = observer(
  ({
    listOfOptions,
    onChangeProp,
    listOfSelectOptions,
  }: IPlayerOpinionMultiSelect) => {
    const [selected, setSelected] = useState(
      listOfOptions.filter((el) => {
        return listOfSelectOptions.map((mOpt) => mOpt.value).includes(el.value);
      })
    );

    const onChange = (currentList: IMultiSelectOption[]) => {
      setSelected(currentList);
      onChangeProp(currentList);
    };

    return (
      <MultiSelect
        options={listOfOptions}
        value={selected}
        onChange={onChange}
        labelledBy="Select"
      />
    );
  }
);

export default PlayersOpinionMultiSelect;
