import { useStore } from "../../store/store";
import { observer } from "mobx-react-lite";
import { IAnswer } from "../../store/classes/answers/IAnswer";
import { Answer } from "./Answer";
import { arToMultiSelect } from "../../store/utils";
import { queryService } from "../../services/Query";
import { messages } from "../../store/classes/messages/Messages";
import { ServerMessagesArea } from "../../enums/ServerMessagesArea";
import { useEffect } from "react";
import { ICheckAnswerResponse } from "../../common/interfaces/responses/ICheckAnswerResponse";
import { ResponseStatuses } from "../../common/enums/responseStatuses";
import { AnswerStatuses } from "../../enums/AnswerStatuses";

interface IListOfAnswers {
  gameId: string;
}
export const ListOfAnswers = observer(({ gameId }: IListOfAnswers) => {
  const { settings, userAnswers } = useStore();
  const onAnswerChange = (answer: IAnswer) => {
    userAnswers.updateAnswer(answer.questionId, answer.data);
    // settings.pickedAnswerId = "";
  };

  useEffect(() => {
          console.log(userAnswers.getAnswersByGameId(settings.pickedGameId));
    userAnswers.reset();
  }, []);

  const onAnswerCheck = async () => {
    const listOfAnswers = userAnswers.getAnswersByGameId(gameId);
    const res: { data: ICheckAnswerResponse } =
      await queryService.noGooglePostQuery("/checkAnswer", {
        gameId: settings.pickedGameId,
        data: listOfAnswers.map((answer) => {
          return {
            questionId: answer.questionId,
            data: answer.data.map((el) => {
              return el.value;
            }),
          };
        }),
      });
    const infoMessageTimeOut = 5000;
    if (res.data.status === ResponseStatuses.error) {
      messages.add(
        {
          text: "Подумайте еще, ответ неверный",
          className: "alert-warning",
          area: ServerMessagesArea.page,
        },
        infoMessageTimeOut
      );
      listOfAnswers.forEach((answer) => {
        answer.status = AnswerStatuses.done;
      });
      res.data.listOfWrongAnswers.forEach((wrongAnswerId) => {
        userAnswers.data[wrongAnswerId].status = AnswerStatuses.failed;
      });
    } else {
      listOfAnswers.forEach((answer) => {
        answer.status = AnswerStatuses.done;
      });
      messages.add(
        {
          text: "Поздравляем! Вы можете найти задачу на странице Завершенные",
          className: "alert alert-success",
          area: ServerMessagesArea.page,
        },
        5000
      );
    }
    setTimeout(() => {
      listOfAnswers.forEach((answer) => {
        answer.status = AnswerStatuses.start;
      });
    }, infoMessageTimeOut);
  };
  return (
    <div style={{ minWidth: 250 + "px", width: 100 + "%" }} className="">      {userAnswers.getAnswersByGameId(settings.pickedGameId).map((el) => {
        return (
          <>
            <Answer
              key={el.questionId}
              listOfOptions={arToMultiSelect(
                settings.playerSettingsAr ?? [],
                "numberValue",
                "numberValue"
              )}
              answer={el}
              onChange={onAnswerChange}
              className={" answer-" + el.status}
            ></Answer>
          </>
        );
      })}
      {userAnswers.getAnswersByGameId(settings.pickedGameId).length > 0 && (
        <div className="d-flex justify-content-end">
          <button onClick={onAnswerCheck} className="btn btn-warning">
            Проверить
          </button>
        </div>
      )}
    </div>
  );
});
