import { IMultiSelectOption } from "../../../components/constructor/opinion/PlayersOpinionMultiSelect";
import { IAnswer } from "./IAnswer";
import { AnswerStatuses } from "../../../enums/AnswerStatuses";
import { makeAutoObservable } from "mobx";

export class Answers {
  data: {
    [questionId: string]: Answer;
  } = {};
  constructor() {
    makeAutoObservable(this);
  }
  add(item: IAnswer) {
    this.data[item.questionId] = new Answer(item);
  }
  getByQuestions(questions: string[]) {
    return this.dataAr.filter((el) => questions.includes(el.questionId));
  }
  updateAnswer(questionId: string, data: IMultiSelectOption[]) {
    this.data[questionId].data = data;
  }
  public reset() {
    this.data = {};
  }
  get dataAr() {
    return Object.values(this.data);
  }
  getAnswersByGameId(gameId: string) {
    console.log("gameId!!!!")
    console.log(gameId)
    return this.dataAr.filter((el) => el.gameId === gameId);
  }
}
class Answer implements IAnswer {
  questionText: string;
  data: IMultiSelectOption[];
  finished: boolean;
  status: AnswerStatuses;
  questionId: string;
  gameId: string;

  constructor(data: IAnswer) {
    makeAutoObservable(this);
    this.data = data.data;
    this.finished = data.finished;
    this.status = data.status;
    this.questionId = data.questionId;
    this.questionText = data.questionText;
    this.gameId = data.gameId;
  }
}
export const answers = new Answers();
