import { MultiSelect } from "react-multi-select-component";
import { IMultiSelectOption } from "../constructor/opinion/PlayersOpinionMultiSelect";
import { MyModal } from "../common/MyModal";
import { useState } from "react";
import { useStore } from "../../store/store";
import { arToMultiSelect } from "../../store/utils";
import { observer } from "mobx-react-lite";
import { IQuestion } from "../../interfaces/IQuestion";
import { questions } from "../../store/classes/questions/Questions";
import { ListOfQuestions } from "./ListOfQuestions";
import { HardLevelPicker } from "./HardLevelPicker";
import { HardLevelForm } from "../hardLevel/HardLevelForm";

interface IAnswerConfiguration {
  listOfOptions: IMultiSelectOption[];
  answer: string;
  gameId: string;
  onSave: (answer: IQuestion) => void;
}
export const QuestionConfiguration = observer(
  ({ listOfOptions, gameId, answer, onSave }: IAnswerConfiguration) => {
    const [localAnswer, setLocalAnswer]: [IQuestion, Function] = useState(
      questions.findOrEmpty(answer)
    );
    const onChange = (selected) => {
      localAnswer.answer = selected;
      setLocalAnswer({ ...localAnswer, gameId: gameId });
    };
    const onFormSend = (e) => {
      e.preventDefault();
      onSave(localAnswer);
      setLocalAnswer(questions.findOrEmpty(""));
    };
    return (
      <form className="mb-2" onSubmit={onFormSend}>
        <div className="form-group">
          <label htmlFor="" className="form-label">
            Напишите вопрос
          </label>
          <textarea
            className="form-control"
            name="question"
            required={true}
            value={localAnswer.question}
            onChange={(e) => {
              setLocalAnswer({
                ...localAnswer,
                [e.target.name]: e.target.value,
              });
            }}
            rows={4}
            cols={40}
            id=""
            placeholder="Вопрос"
          />
        </div>
        <div className="form-group">
          <label htmlFor="" className="form-label">
            Выберите ответ
          </label>
          <MultiSelect
            options={listOfOptions}
            value={localAnswer.answer}
            onChange={onChange}
            labelledBy="Select"
          ></MultiSelect>
        </div>
        <div className="d-flex justify-content-end">
          <button type="submit" className="btn btn-warning mt-2 mb-2x">
            Сохранить
          </button>
        </div>
      </form>
    );
  }
);
export const AnswerBlock = observer(() => {
  const [isModalShown, setIsModalShown] = useState(false);
  const { settings, playersOpinionGl, players, rounds, answersGl, games } =
    useStore();

  const [rangeValue, setRangeValue] = useState(1);

  const onModalOpen = () => {};
  const onModalClose = () => {
    setIsModalShown(false);
  };
  const onAnswerSave = (answer: IQuestion) => {
    questions.add(answer);
    // settings.pickedAnswerId = "";
  };

  const openModal = () => {
    setIsModalShown(true);
  };
  const onRangeChange = (newVal: number) => {
    const currentGame = games.findById(settings.pickedGameId);
    currentGame.hardLevel = newVal;
  };

  return (
    <>
      {isModalShown && (
        <MyModal
          isShown={isModalShown}
          onOpen={onModalOpen}
          onClose={onModalClose}
          title="Добавление ответа"
        >
          <HardLevelForm
            initRangeValue={rangeValue}
            onValChange={onRangeChange}
          />
          <QuestionConfiguration
            listOfOptions={arToMultiSelect(
              settings.playerSettingsAr.map((el) => {
                return {
                  ...el,
                  value: el.value + 1,
                };
              }) ?? [],
              "value",
              "value"
            )}
            answer={settings.pickedAnswerId}
            onSave={onAnswerSave}
            gameId={settings.pickedGameId}
          />
          <ListOfQuestions
            list={questions.getByGameId(settings.pickedGameId)}
          />
        </MyModal>
      )}
      <button
        className="btn btn-warning round-element round-container"
        onClick={openModal}
      >
        <span className="round-container-title">Добавить ответ</span>
      </button>
    </>
  );
});
