import { GameField } from "../../constructor/GameField";
import React, { useEffect, useState } from "react";
import { useStore } from "../../../store/store";
import { Round } from "../../../store/classes/rounds/Rounds";
import { observer } from "mobx-react-lite";
interface IUserGame {
  globalGameId: string;
}
export const UserGame = observer(({ globalGameId }: IUserGame) => {
  const { games, settings, playersOpinionGl, rounds, players } = useStore();

  const onPickRound = (round: Round) => {
    settings.pickedRoundId = round.data.id;
  };
  const [isModalShown, setIsModalShown] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);

  const loadGame = async () => {
    await games.initUserGame(globalGameId);
    await setIsLoaded(true);
    console.log("раунд!!!!");
    console.log(rounds.getRoundIdByIndex(0, globalGameId));
    settings.pickedRoundId = rounds.getRoundIdByIndex(0, globalGameId);
  };

  useEffect(() => {
    loadGame();
  }, []);
  return (
    <>
      {isLoaded && (
        <div className="">
          {settings.elementRadius && settings.pickedRoundId && (
            // <div className="card">
            <>
              <GameField
                style={{
                  position: "relative",
                  width: settings.screenGameWidth + "px",
                }}
                roundId={settings.pickedRoundId}
              />
            </>
          )}
        </div>
      )}
    </>
  );
});
