import { makeAutoObservable } from "mobx";
import axios from "axios";
import { serverUrl } from "../env";
import { messages } from "../store/classes/messages/Messages";
import { ServerMessagesArea } from "../enums/ServerMessagesArea";
import { IUserResp } from "../interfaces/IUserResp";
import { Cookies } from "typescript-cookie";
import { ResponseStatuses } from "../common/enums/responseStatuses";

class QueryService {
  public googleId: string = "";
  public refreshToken: string = "";
  public accessToken: string = "";
  public accessTokenExtTime: number = 0;
  public currentUser: IUserResp = {} as IUserResp;

  constructor() {
    makeAutoObservable(this);
  }

  /**
   * Обертка для запроса без токена.
   * @param uri
   * @param data
   */
  async noTokenQuery(uri, data) {
    try {
      return await axios.post(
        serverUrl + uri,
        {
          ...data,
        },
        {
          withCredentials: true,
          // headers: {
          //   "Access-Control-Allow-Origin": "*",
          //   "Content-Type": "application/json",
          // },
        }
      );
    } catch (e) {
      messages.add(
        {
          className: "alert-warning",
          text: e?.response?.data?.msg ?? "Неизвестная ошибка",
          area: ServerMessagesArea.page,
        },
        5000
      );
    }
  }

  /**
   * Запрос для выхода из аккаунта
   * @param uri
   * @param data
   */
  async tokenWithCookieQuery(uri, data) {
    try {
      await this.getAccessToken();
      const config = {
        withCredentials: true,
        headers: { Authorization: `Bearer ${this.accessToken}` },
      };
      const resp = await axios.post(
        serverUrl + uri,
        {
          ...data,
          mafId: this.currentUser._id,
        },
        config
      );
      if (resp?.data?.status === ResponseStatuses.error) {
        throw new Error(resp.data.msg ?? "Неизвестная ошибка");
      }
      return resp;
    } catch (e) {
      messages.add(
        {
          className: "alert-warning",
          text: e,
          area: ServerMessagesArea.page,
        },
        5000
      );
    }
  }

  /**
   * Обертка для запросов с токенами.
   * @param uri
   * @param data
   */
  async noGooglePostQuery(uri, data) {
    try {
      await this.getAccessToken();
      const config = {
        headers: { Authorization: `Bearer ${this.accessToken}` },
      };
      const resp = await axios.post(
        serverUrl + uri,
        {
          ...data,
        },
        config
      );
      // if (resp?.data?.status === ResponseStatuses.error) {
      //   throw new Error(resp.data.msg ?? "Неизвестная ошибка");
      // }
      return resp;
    } catch (e) {
      messages.add(
        {
          className: "alert-warning",
          text: e,
          area: ServerMessagesArea.page,
        },
        5000
      );
    }
  }

  /**
   * Получить токен доступа
   */
  public async getAccessToken() {
    if (
      this.accessToken == "" ||
      Math.floor(Date.now() / 1000) + 10 >= this.accessTokenExtTime
    ) {
      const resp = await this.noTokenQuery("/getMailToken", {});

      if (resp?.data.status == ResponseStatuses.ok) {
        this.accessToken = resp.data.token;
        this.currentUser = resp.data.user;
        this.accessTokenExtTime = resp.data.expTime;
      } else {
        throw new Error("Проблемы с доступом");
      }
    }
  }
}
export const queryService = new QueryService();
