import { useEffect, useState } from "react";
import { RoundTypes } from "../../common/enums/RoundTypes";
import { IRoundInfo } from "../../common/interfaces/round/IRoundInfo";
import { uuidv4 } from "../../store/utils";
import { IPlayerInfo } from "../../common/interfaces/player/IPlayerInfo";
import { useStore } from "../../store/store";
import { Players } from "../../store/classes/players/Players";

export const AddRoundComponent = () => {
  const [roundType, setRoundType]: [RoundTypes, Function] = useState();
  const [roundTitle, setRoundTitle]: [string, Function] = useState("");
  const [roundTitlePlaceHolder, setRoundTitlePlaceHolder] = useState("");

  const onRoundTypeChange = (e) => {
    setRoundType(e.target.value);
  };
  const { settings, playersOpinionGl, rounds, players } = useStore();

  const sendForm = (e) => {
    e.preventDefault();
    addNewRound(settings.pickedGameId);
  };

  const getRoundPlaceHolder = (gameId: string, roundType: RoundTypes) => {
    return (
      "Например:" +
      roundType +
      " №" +
      rounds.getLastRoundIndexByRoundTypeAndGameId(gameId, roundType)
    );
  };

  useEffect(() => {
    if (roundType) {
      setRoundTitlePlaceHolder(
        getRoundPlaceHolder(settings.pickedGameId, roundType)
      );
    }
  }, [roundType]);

  const addNewRound = (gameId: string) => {
    const previousRound = rounds.getLastRoundByGameId(gameId);
    const newRoundId = uuidv4();
    const round: IRoundInfo = {
      ...previousRound.data,
      id: newRoundId,
      type: roundType,
      title: roundTitle,
    };
    rounds.add(round);
    const listOfPlayers = players.getPlayersByRoundId(previousRound.data.id);
    listOfPlayers.forEach((player) => {
      let newPlayerId = uuidv4();
      players.add({
        ...player,
        id: newPlayerId,
        roundId: newRoundId,
      });
      if (roundType === previousRound.data.type) {
        const listOfOpinions = playersOpinionGl.getOpinionByPlayerId(player.id);
        listOfOpinions.forEach((el) => {
          playersOpinionGl.add({
            ...el,
            id: uuidv4(),
            player_id: newPlayerId,
          });
        });
      }
    });
  };

  return (
    <form onSubmit={(e) => sendForm(e)}>
      <div className="mb-3">
        <label htmlFor="disabledTextInput" className="form-label">
          Выберите тип раунда
        </label>
        <select
          required
          value={roundType}
          onChange={onRoundTypeChange}
          id="disabledTextInput"
          className="form-control"
          placeholder="Disabled input"
        >
          <option value="">Выберите значение</option>
          {Object.values(RoundTypes).map((el) => {
            return <option value={el}>{el}</option>;
          })}
        </select>
      </div>
      <div className="mb-3">
        <label htmlFor="round-title-name" className="form-label">
          Название раунда
        </label>
        <input
          type="text"
          key={roundType}
          value={roundTitle}
          placeholder={roundTitlePlaceHolder}
          onChange={(e) => setRoundTitle(e.target.value)}
          id="round-title-name"
          className="form-control"
        />
      </div>
      <div className="mt-3 ">
        <button type="submit" className="btn btn-success">
          Добавить
        </button>
      </div>
    </form>
  );
};
