import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { ServerMessagesArea } from "../../../enums/ServerMessagesArea";
import { queryService } from "../../../services/Query";
import { useNavigate } from "react-router";
import { setAuthParams } from "../../../store/utils";
import { COOKIE_EXP_DAYS } from "../../../env";

export const MailRegistration = observer(() => {
  const { userRegGl, messagesGl } = useStore();
  const navigate = useNavigate();
  const changeUserRegParam = (e) => {
    userRegGl[e.target.name] = e.target.value;
  };
  const sendForm = async (e) => {
    e.preventDefault();
    const regRes = await userRegGl.registration();
    if (regRes?.status == 2) {
      await messagesGl.add(
        {
          className: "alert-warning",
          text: regRes.data.msg,
          area: ServerMessagesArea.page,
        },
        5000
      );
    } else {
      setAuthParams(regRes.data.mafId, regRes.data.expTime, COOKIE_EXP_DAYS);
      navigate("/list");
    }
  };
  return (
    <div className="row justify-content-center align-items-center">
      <div className="col-md-12 col-lg-6 mt-8">
        <form
          action=""
          className=" bg-white p-7"
          style={{ borderRadius: 20 + "px" }}
          onSubmit={sendForm}
        >
          <div className="row mb-2 justify-content-center">
            <label
              htmlFor="email"
              className="form-label col-md-5 col-lg-4 d-flex align-items-center"
              style={{ whiteSpace: "nowrap" }}
            >
              Введите почту
            </label>
            <div className="col-md-7 col-lg-8">
              <input
                name="email"
                required
                onChange={changeUserRegParam}
                value={userRegGl.email}
                type="text"
                id="email"
                className="form-control"
              />
            </div>
          </div>
          <div className="row mb-2 justify-content-center">
            <label
              htmlFor="userName"
              className="form-label col-md-5 col-lg-4 d-flex align-items-center"
              style={{ whiteSpace: "nowrap" }}
            >
              Введите ник
            </label>
            <div className="col-md-7 col-lg-8">
              <input
                name="userName"
                required
                onChange={changeUserRegParam}
                value={userRegGl.userName}
                type="text"
                id="userName"
                className="form-control"
              />
            </div>
          </div>
          <div className="row mb-2 justify-content-center">
            <label
              htmlFor="password"
              className="form-label col-md-5 col-lg-4 d-flex align-items-center"
              style={{ whiteSpace: "nowrap" }}
            >
              Введите пароль
            </label>
            <div className="col-md-7 col-lg-8">
              <input
                name="password"
                required
                onChange={changeUserRegParam}
                value={userRegGl.password}
                type="password"
                id="password"
                className="form-control"
              />
            </div>
          </div>
          <div className="row mb-2 justify-content-center">
            <label
              htmlFor="repeatedPassword"
              className="form-label col-md-5 col-lg-4 d-flex align-items-center"
              style={{ whiteSpace: "nowrap" }}
            >
              Повторите пароль
            </label>
            <div className="col-md-7 col-lg-8">
              <input
                type="password"
                required
                onChange={changeUserRegParam}
                name="repeatedPassword"
                value={userRegGl.repeatedPassword}
                id="repeatedPassword"
                className="form-control"
              />
            </div>
          </div>
          <div className="d-flex justify-content-end">
            <button className="btn btn-warning">Регистрация</button>
          </div>
        </form>
      </div>
    </div>
  );
});
