import { observer } from "mobx-react-lite";
import { useStore } from "../../store/store";
import { PlayerPositions } from "../../common/enums/PlayerPositionTypes";
import { RoundTypes } from "../../common/enums/RoundTypes";
import { useState } from "react";
import { ISherCheck } from "../../common/interfaces/player/IPlayerInfo";
import { setHelper } from "../../store/utils";
import { useNavigate } from "react-router";
import { SherChecks } from "../pages/userGame/SherChecks";
import { sherChecksGl } from "../../globalConst/sherChecksGl";

interface ISherCheckPanel {
  pickedRoundId: string;
  pickedPlayerId: string;
}
export const SherCheckPanel = observer(
  ({ pickedRoundId, pickedPlayerId }: ISherCheckPanel) => {
    const { settings, playersOpinionGl, rounds, players } = useStore();

    return (
      <div>
        {players.data[pickedPlayerId].sherCheckAr.map((el) => {
          return el.id;
        })}
        <AddSherCheckComponent
          pickedRoundId={pickedRoundId}
          pickedPlayerId={pickedPlayerId}
        />
        <SherChecks pickedPlayerId={settings.pickedPlayerId}></SherChecks>
      </div>
    );
  }
);
interface IAddSherCheckComponent {
  pickedRoundId: string;
  pickedPlayerId: string;
}
export const AddSherCheckComponent = observer(
  ({ pickedRoundId, pickedPlayerId }: IAddSherCheckComponent) => {
    const { rounds, players, settings } = useStore();
    const navigate = useNavigate();

    const [sherCheck, setSherCheck]: [ISherCheck, Function] = useState(
      {} as ISherCheck
    );
    const onSave = (e) => {
      e.preventDefault();
      const player = players.findOrEmpty(pickedPlayerId);
      player.sherCheck[sherCheck.roundId] = {
        roundId: sherCheck.roundId,
        playerId: sherCheck.playerId,
        playerCheck: sherCheck.playerCheck,
      };
      setSherCheck({ playerCheck: "", playerId: "", roundId: "" });
    };
    return (
      <form onSubmit={onSave}>
        <div className="form-group mb-2">
          <label htmlFor="">Выберите ночь</label>
          <select
            required
            value={sherCheck.roundId}
            onChange={(e) => setHelper(setSherCheck, e)}
            name="roundId"
            id=""
            className="form-control"
          >
            <option value="">Не выбрано</option>
            {rounds
              .getRoundsByGameId(settings.pickedGameId)
              .filter((el) => el.data.type === RoundTypes.night)
              .map((nightRound, index) => {
                return (
                  <option value={nightRound.data.id}>Ночь {index + 1}</option>
                );
              })}
          </select>
        </div>
        <div className="form-group mb-2">
          <label htmlFor="">Выберите игрока</label>
          <select
            required
            onChange={(e) => setHelper(setSherCheck, e)}
            value={sherCheck.playerId}
            name="playerId"
            className="form-control"
            id=""
          >
            <option value="">Не выбрано</option>
            {players
              .getPlayersByRoundId(pickedRoundId)
              .filter((el) => el.id != pickedPlayerId)
              .map((player) => {
                return <option value={player.id}>{player.text}</option>;
              })}
          </select>
        </div>
        <div>
          <label htmlFor="">Выберите проверку</label>
          <select
            required
            value={sherCheck.playerCheck}
            onChange={(e) => setHelper(setSherCheck, e)}
            name="playerCheck"
            id=""
            className="form-control"
          >
            <option value="">Не выбрано</option>
            <option value={PlayerPositions.red}>
              {sherChecksGl[PlayerPositions.red]}
            </option>
            <option value={PlayerPositions.black}>
              {sherChecksGl[PlayerPositions.black]}
            </option>
          </select>
        </div>
        <div className="d-flex justify-content-end"></div>
        <button type="submit" className="btn btn-warning mt-2 ">
          Добавить
        </button>
      </form>
    );
  }
);
