import { Range } from "react-range";
import { useState } from "react";

export interface IHardLevelPicker {
  startValue: number;
  onValueChange: (newVal: number) => any;
  key?: any;
}
export const HardLevelPicker = ({
  startValue,
  onValueChange,
}: IHardLevelPicker) => {
  const [range, setRange] = useState({ values: [startValue] });
  const onChange = (values: number[]) => {
    setRange({ values });
    // console.log(values[0]);
    onValueChange(values[0]);
  };
  return (
    <div className="mb-3 d-flex align-items-center">
      <span className="me-2">Выберите сложность</span>
      <Range
        step={1}
        min={1}
        max={5}
        values={range.values}
        onChange={onChange}
        renderTrack={({ props, children }) => (
          <div
            {...props}
            style={{
              ...props.style,
              height: "6px",
              width: "30%",
              backgroundColor: "#030303",
            }}
          >
            {children}
          </div>
        )}
        renderThumb={({ props }) => (
          <div
            {...props}
            style={{
              ...props.style,
              height: "15px",
              width: "15px",
              borderRadius: 10 + "px",
              backgroundColor: "#f60000",
            }}
          />
        )}
      />
      <div className="hard-level ms-2">
        {/*<div className={"hard-level-icon hard-level-icon-" + range.values[0]}>*/}
        {/*  <div className="hard-level-icon-text">{range.values[0]}</div>*/}
        {/*</div>*/}
        <div
          className="d-flex hard-level-stars"
          style={{ fontSize: 20 + "px" }}
        >
          {new Array(range.values[0]).fill("&#9733;").map((el) => {
            return <div dangerouslySetInnerHTML={{ __html: "&#9733;" }} />;
          })}
        </div>
      </div>
    </div>
  );
};
