import { makeAutoObservable } from "mobx";
import { IRoundInfo } from "../../../common/interfaces/round/IRoundInfo";
import { players } from "../players/Players";
import { IStoreObject } from "../../interfaces/IStoreObject";
import { messages } from "../messages/Messages";
import { ServerMessagesArea } from "../../../enums/ServerMessagesArea";
import { gameSettings } from "../temp/TempSettings";
import { RoundTypes } from "../../../common/enums/RoundTypes";

export class Rounds implements IStoreObject<IRoundInfo> {
  public data: {
    [id: string]: Round;
  } = {};
  constructor() {
    makeAutoObservable(this, {}, { deep: true, autoBind: true });
  }
  add = (round: IRoundInfo) => {
    this.data[round.id] = new Round(round);
  };
  get dataAr() {
    let keys = Object.keys(this.data);
    return keys.length > 0 ? keys.map((key) => this.data[key]) : [];
  }
  getRoundIndex(roundId: string, gameId: string) {
    return this.dataAr
      .filter(
        (round) =>
          round.data.gameId === gameId &&
          round.data.type === this.data[roundId].data.type
      )
      .sort()
      .map((el, index) => {
        return {
          rId: el.data.id,
          rIndex: index + 1,
        };
      })
      .find((el) => el.rId === roundId);
  }
  getRoundIdByIndexAndType(
    index: number,
    gameId: string,
    roundType: RoundTypes
  ) {
    return this.dataAr
      .filter(
        (round) => round.data.gameId === gameId && round.data.type === roundType
      )
      .sort()
      .find((el, rIndex) => {
        return rIndex === index;
      })?.data.id;
  }
  getRoundIdByIndex(index: number, gameId: string) {
    console.log("Отфильтрованная игра")
    console.log(gameId)
    console.log(this.dataAr.filter((game) => game.data.gameId === gameId));
    return this.dataAr
      .filter((game) => game.data.gameId === gameId)
      .sort()
      .find((el, rIndex) => {
        return rIndex === index;
      })?.data.id;
  }
  getLastRoundByGameId(gameId: string): Round {
    return this.dataAr
      .filter((r) => r.data.gameId === gameId)
      .find((r, index, ar) => {
        return index === ar.length - 1;
      });
  }
  getRoundTitle(roundId: string, gameId: string) {
    return (
      this.data[roundId].data.type +
      " №" +
      this.getRoundIndex(roundId, gameId).rIndex
    );
  }
  getLastRoundIndexByRoundTypeAndGameId(gameId: string, roundType: RoundTypes) {
    const filtredRound = this.dataAr
      .filter((el) => el.data.gameId === gameId)
      .filter((el) => el.data.type === roundType);

    return filtredRound.length ? filtredRound.length + 1 : 1;
  }
  getByGameId(gameId: string) {
    return this.dataAr.filter((el) => el.data.gameId == gameId);
  }
  public findById(id: string) {
    return this.data[id].data ?? {};
  }
  init(data: { [id: string]: IRoundInfo }) {
    Object.keys(data).forEach((key) => {
      this.add(data[key]);
    });
  }
  public getRoundsByGameId(gameId: string) {
    console.log("Найти раунд!!!");
    console.log(gameId);
    return this.dataAr.filter((el) => {
      return el.data.gameId == gameId;
    });
  }
  public delete(roundId) {
    if (roundId == gameSettings.pickedRoundId) {
      messages.add({
        className: "alert-danger",
        text: "Нельзя удалить выбранный раунд",
        area: ServerMessagesArea.page,
      });
      return false;
    }
    delete this.data[roundId];
    messages.add(
      {
        className: "alert-info",
        text: "Не забудь сохранить",
        area: ServerMessagesArea.page,
      },
      2000
    );
    players.getPlayersByRoundId(roundId).forEach((player) => {
      players.delete(player.id);
    });
  }
}
export class Round {
  get numberOfPlayers() {
    return players.playersAr.filter((player) => this.data.id == player.roundId)
      .length;
  }

  set numberOfPlayers(value) {
    this._numberOfPlayers = value;
  }
  public data: IRoundInfo;
  constructor(round: IRoundInfo) {
    this.data = round;
    makeAutoObservable(this, {}, { deep: true, autoBind: true });
  }
  private _numberOfPlayers: number = 0;
}

export const rounds = new Rounds();
