import { observer } from "mobx-react-lite";
import { useStore } from "../../../store/store";
import { IPlayerOpinionInfo } from "../../../common/interfaces/playerOpinion/IPlayerOpinionInfo";
import React, { useState } from "react";
import { onMultiSelectWrap, uuidv4 } from "../../../store/utils";
import PlayersOpinionMultiSelect, {
  IMultiSelectOption,
} from "../opinion/PlayersOpinionMultiSelect";
import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";
import { LifeSelect } from "../LifeSelect";
import { SherCheckPanel } from "../SherCheckPanel";
import { AddComment } from "../comment/AddComment";
import { Rounds } from "../../../store/classes/rounds/Rounds";

export const DayPanel = observer(
  ({
    key,
    playerId,
    pickedPlayerOpinion,
    pickedRoundId,
  }: {
    key?: any;
    playerId: string;
    pickedPlayerOpinion: string;
    pickedRoundId: string;
  }) => {
    const { settings, playersOpinionGl, players, rounds } = useStore();
    const [currentPlayerOpinion, setCurrentPlayerOpinion]: [
      IPlayerOpinionInfo,
      any
    ] = useState(playersOpinionGl.finedOrEmpty(pickedPlayerOpinion));
    const savePlayerOpinion = (e) => {
      e.preventDefault();
      playersOpinionGl.add({
        ...currentPlayerOpinion,
        ...{ player_id: playerId, id: uuidv4() },
      });
    };
    const onSherChange = (e) => {
      const currentPlayer = players.findOrEmpty(settings.pickedPlayerId);
      currentPlayer.isSher = e.target.checked;
    };
    const onCommentChange = (newValue: string) => {
      const r = rounds as Rounds;
      r.data[settings.pickedRoundId].data.comment = newValue;
    };

    const commentWrapper = (roundId: string) => {
      return (newValue: string) => {
        rounds.data[roundId].data.comment = newValue;
      };
    };
    const getCommentText = (roundId: string) => {
      return rounds.data[settings.pickedRoundId].data.comment;
    };

    return (
      <>
        <form onSubmit={savePlayerOpinion}>
          <div className="form-group mb-3">
            <label htmlFor="pickedPlayer">Выберите мафию</label>
            <PlayersOpinionMultiSelect
              key={playerId + "_" + PlayerPositions.black}
              listOfOptions={players
                .getPlayersByRoundIdAndOpinion(
                  pickedRoundId,
                  PlayerPositions.black,
                  playerId
                )
                .map((el) => {
                  return {
                    label: el.text,
                    value: el.id,
                  };
                })}
              onChangeProp={onMultiSelectWrap(
                playerId,
                PlayerPositions.black,
                playersOpinionGl
              )}
              listOfSelectOptions={playersOpinionGl
                .getOpinionByPlayerId(playerId)
                .filter((el) => el.opinionType === PlayerPositions.black)
                .map((el) => {
                  return {
                    label: el.numberValue,
                    value: el.to,
                  };
                })}
            ></PlayersOpinionMultiSelect>
          </div>
          <div className="form-group mb-3">
            <label htmlFor="pickedPlayer">Выберите мирных</label>
            <PlayersOpinionMultiSelect
              key={playerId + "_" + PlayerPositions.red}
              listOfOptions={players
                .getPlayersByRoundIdAndOpinion(
                  pickedRoundId,
                  PlayerPositions.red,
                  playerId
                )
                .map((el) => {
                  return {
                    label: el.text,
                    value: el.id,
                  };
                })}
              listOfSelectOptions={playersOpinionGl
                .getOpinionByPlayerId(playerId)
                .filter((el) => el.opinionType === PlayerPositions.red)
                .map((el) => {
                  return {
                    label: el.numberValue,
                    value: el.to,
                  };
                })}
              onChangeProp={onMultiSelectWrap(
                playerId,
                PlayerPositions.red,
                playersOpinionGl
              )}
            ></PlayersOpinionMultiSelect>
          </div>
          <div className="form-group mb-3">
            {settings.pickedRoundId && (
              <LifeSelect roundId={settings.pickedRoundId} />
            )}
          </div>
        </form>
        <div className="form-group">
          <label className="form-label me-2" htmlFor="sher">
            Шериф
          </label>
          <input
            key={settings.pickedPlayerId}
            className="form-check-input"
            onChange={onSherChange}
            checked={players.findOrEmpty(settings.pickedPlayerId)?.isSher}
            id="sher"
            type="checkbox"
          />
        </div>
        <div className="form-group">
          <AddComment roundId={pickedRoundId} />
        </div>
        {settings.pickedRoundId &&
          settings.pickedPlayerId &&
          players.findOrEmpty(settings.pickedPlayerId).isSher && (
            <SherCheckPanel
              pickedRoundId={settings.pickedRoundId}
              pickedPlayerId={settings.pickedPlayerId}
            />
          )}
      </>
    );
  }
);
