import { MyModal } from "../../common/MyModal";
import { AddRoundComponent } from "../AddRounComponent";
import React, { useState } from "react";

export const RoundModal = () => {
  const [isModalShown, setIsModalShown] = useState(false);
  const onModalOpen = () => {
    setIsModalShown(true);
  };
  const onModalClose = () => {
    setIsModalShown(false);
  };

  return (
    <>
      <button
        className="btn btn-primary round-element round-container"
        onClick={onModalOpen}
      >
        <span className="round-container-title">Добавить Раунд</span>
      </button>
      {isModalShown && (
        <MyModal
          isShown={isModalShown}
          onOpen={onModalOpen}
          onClose={onModalClose}
          title="Добавить раунд"
        >
          <AddRoundComponent />
        </MyModal>
      )}
    </>
  );
};
