import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";
import { players } from "../../../store/classes/players/Players";
import { SherChecks } from "./SherChecks";
import { sherChecksGl } from "../../../globalConst/sherChecksGl";

interface IPlayerPositionComment {
  userOpinionObj: {
    [playerPosType in PlayerPositions]: string[];
  };
  selectedUser: string;
}
export const PlayerPositionComment = ({
  userOpinionObj,
  selectedUser,
}: IPlayerPositionComment) => {
  const getUserName = (id: string) => {
    return "Игрок №" + (players.findOrEmpty(id).numberValue + 1);
  };

  return (
    <div className="card ">
      <div className="card-header">
        Мнение игрока №{players.findOrEmpty(selectedUser).numberValue + 1}
      </div>
      <div className="card-body">
        {Object.keys(userOpinionObj).map((posKey) => {
          if (userOpinionObj[posKey as PlayerPositions].length == 0)
            return <></>;
          return (
            <p style={{ textAlign: "left" }}>
              {sherChecksGl[posKey]}:
              {userOpinionObj[posKey as PlayerPositions].map((playerId) => {
                return (
                  <span className="text-black">
                    {getUserName(playerId) + " "}
                  </span>
                );
              })}
            </p>
          );
        })}
        <SherChecks pickedPlayerId={selectedUser}></SherChecks>
      </div>
    </div>
  );
};
