import { MyModal } from "../common/MyModal";
import { useState } from "react";
import { queryService } from "../../services/Query";
import { ShowStatuses } from "../../common/enums/ShowStatuses";
import { observer } from "mobx-react-lite";
import { useStore } from "../../store/store";
import { ServerMessagesArea } from "../../enums/ServerMessagesArea";

export interface IManageSettingsModal {
  isModalShown: boolean;
  onClose: () => any;
  currentShowStatus: ShowStatuses;
  gameId: string;
}

export const ManageSettingsModal = observer(
  ({
    isModalShown,
    onClose,
    currentShowStatus,
    gameId,
  }: IManageSettingsModal) => {
    const [currentStatus, setCurrentStatus] = useState(currentShowStatus);
    const { messagesGl } = useStore();

    const onSave = async (e) => {
      e.preventDefault();
      // alert(currentStatus);
      await queryService.noGooglePostQuery("/game/changeShowStatus", {
        showStatus: currentStatus,
        gameId: gameId,
      });
      messagesGl.add(
        {
          text: "Успешно изменили статус",
          className: "alert-success",
          area: ServerMessagesArea.page,
        },
        1000
      );
    };
    return (
      <>
        {isModalShown && (
          <MyModal
            isShown={isModalShown}
            onOpen={() => {}}
            onClose={onClose}
            title={"Настройка видимости"}
          >
            <form action="" onSubmit={onSave}>
              <div className="form-group">
                <label htmlFor="access-select" className="form-label">
                  Кому доступна ваша задача?
                </label>
                <select
                  className="form-control"
                  id="access-select"
                  onChange={(e) => {
                    setCurrentStatus(e.target.value as unknown as ShowStatuses);
                  }}
                >
                  <option value={ShowStatuses.forMe}>Только я</option>
                  <option value={ShowStatuses.forAll}>Все пользователи</option>
                </select>
                <div className="mt-2 d-flex justify-content-end">
                  <button type="submit" className="btn btn-warning">
                    Сохранить
                  </button>
                </div>
              </div>
            </form>
          </MyModal>
        )}
      </>
    );
  }
);
