import { IQuestion } from "../../interfaces/IQuestion";
import { render } from "@testing-library/react";
import { useStore } from "../../store/store";
import { questions } from "../../store/classes/questions/Questions";

interface IListOfAnswers {
  list: IQuestion[];
}
export const ListOfQuestions = ({ list }: IListOfAnswers) => {
  const { answersGl } = useStore();
  const onDel = (id: string) => {
    answersGl.delete(id);
  };
  return (
    <>
      {list.map((el, index) => {
        return (
          <AnswerView onDelete={onDel} index={index} key={el.id} answer={el} />
        );
      })}
    </>
  );
};

interface IAnswerView {
  answer: IQuestion;
  key: string;
  index: number;
  onDelete: (id: string) => any;
}
export const AnswerView = ({ answer, index, onDelete }: IAnswerView) => {
  const handleDelete = () => {
    onDelete(answer.id);
  };
  return (
    <div className="card mb-2">
      <div className="m-2">
        <div className="d-flex justify-content-between">
          <div>Вопрос #{index + 1}</div>
          <div>
            <button className="btn btn-danger" onClick={handleDelete}>
              x
            </button>
          </div>
        </div>
        <div>{answer.question}</div>
        <div>Ответ: {answer.answer.map((el) => el.label).join(",")}</div>
      </div>
    </div>
  );
};
