import React, { useEffect } from "react";
import "./App.css";
import { createHashRouter, RouterProvider } from "react-router-dom";
import { MainGamePage } from "./components/pages/game/MainGamePage";
import { UserGamePage } from "./components/pages/userGame/UserGamePage";
import { NewGamePage } from "./components/pages/newGame/NewGamePage";
import { ListOfGamesPage } from "./components/pages/list/ListOfGamesPage";
import { MailPage } from "./components/pages/mailReg/MailPage";
import { observer } from "mobx-react-lite";
import { MailAuthPage } from "./components/pages/mailAuth/MailAuthPage";
import { ProtectedRoute } from "./components/wrappers/ProtectedRoute";
import { CommentsPage } from "./components/pages/comments/CommentsPage";
import { TgAuthPage } from "./components/pages/TgAuthPage";

const router = createHashRouter([
  {
    path: "/",
    element: (
      <ProtectedRoute key="main">
        {" "}
        <ListOfGamesPage url="/list" key={"/list"} />
      </ProtectedRoute>
    ),
  },
  {
    path: "/comments",
    element: (
      <ProtectedRoute key="main">
        {" "}
        <CommentsPage />
      </ProtectedRoute>
    ),
  },
  {
    path: "/games/my",
    element: (
      <ProtectedRoute key="/games/my">
        <ListOfGamesPage
          showManagementPanel={true}
          url="/getMyGames"
          key={"/getMyGames"}
        />
      </ProtectedRoute>
    ),
  },
  {
    path: "games/:gameId",
    element: (
      <ProtectedRoute key="games">
        <UserGamePage />
      </ProtectedRoute>
    ),
  },
  {
    path: "games/finished",
    element: (
      <ProtectedRoute key="games/finished">
        <ListOfGamesPage
          url="/getListOfSolvedGames"
          key={"/getListOfSolvedGames"}
        />
      </ProtectedRoute>
    ),
  },
  {
    path: "games/edit/:gameId",
    element: (
      <ProtectedRoute key={"games/edit/"}>
        <MainGamePage />
      </ProtectedRoute>
    ),
  },
  {
    path: "games/new/",
    element: (
      <ProtectedRoute key="games/new/">
        <NewGamePage />
      </ProtectedRoute>
    ),
  },
  {
    path: "/list",
    element: (
      <ProtectedRoute key="/list">
        <ListOfGamesPage url="/list" key={"/list"} />
      </ProtectedRoute>
    ),
  },
  {
    path: "/registration",
    element: <MailPage />,
  },
  {
    path: "/mailAuth",
    element: <MailAuthPage />,
  },
  {
    path: "/tgAuth",
    element: <TgAuthPage />,
  },
]);
const App = observer((props, context) => {
  return (
    <div className="App">
      <RouterProvider router={router} />
    </div>
  );
});

export default App;
