import { observer } from "mobx-react-lite";
import React from "react";
import { useStore } from "../../../store/store";
import { ListOfConnections } from "../../ListOfConnections";
import { PlayingField } from "../../constructor/PlayingField";

interface IGameField {
  roundId: string;
  className: string;
  style?: any;
  key: any;
}
export const SmallGameField = observer(
  ({ roundId, style, className = "" }: IGameField) => {
    const { settings, playersOpinionGl, players, rounds } = useStore();

    return (
      <>
        {roundId && (
          <PlayingField className={className} style={style} roundId={roundId}>
            <ListOfConnections roundId={roundId} />
          </PlayingField>
        )}
      </>
    );
  }
);
