import { configure, makeAutoObservable } from "mobx";
import { IPlayerOpinionInfo } from "../../../common/interfaces/playerOpinion/IPlayerOpinionInfo";
import { IStoreObject } from "../../interfaces/IStoreObject";
import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";

configure({
  enforceActions: "never",
});
export class PlayersOpinion implements IStoreObject<PlayersOpinion> {
  data: {
    [id: string]: PlayerOpinion;
  } = {};

  constructor() {
    makeAutoObservable(this);
  }
  public add(playerOpinion: IPlayerOpinionInfo) {
    let alreadyInData = this.dataAr.find((el) => {
      return (
        playerOpinion.player_id == el.player_id &&
        playerOpinion.to == el.to &&
        playerOpinion.opinionType === el.opinionType
      );
    });
    if (alreadyInData) return false;
    this.data[playerOpinion.id] = new PlayerOpinion(playerOpinion);
  }
  get dataAr(): PlayerOpinion[] {
    return Object.keys(this.data).map((key) => this.data[key]);
  }
  getOpinionByPlayerId(playerId: string) {
    return this.dataAr.filter((el) => el.player_id == playerId);
  }
  createEmpty(): IPlayerOpinionInfo {
    return {} as IPlayerOpinionInfo;
  }
  finedOrEmpty(id: string): IPlayerOpinionInfo {
    return this.data[id] ?? this.createEmpty();
  }
  init(data: any) {
    Object.keys(data).forEach((key) => {
      this.add(data[key]);
    });
  }
  where(howToFind: (player: PlayerOpinion) => boolean) {
    return this.dataAr.filter(howToFind);
  }
  delete(opinionId: string) {
    delete this.data[opinionId];
  }
  getByPlayerIdAndOpinionType(
    playerId: string,
    opinionType: PlayerPositions
  ): { [id: string]: string } {
    return this.where((playerOp) => {
      return (
        playerId === playerOp.player_id && playerOp.opinionType === opinionType
      );
    })
      .map((el) => {
        return {
          id: el.id,
          to: el.to,
        };
      })
      .reduce(
        (previousValue, currentValue) => ({
          ...previousValue,
          [currentValue.to]: currentValue.id,
        }),
        {}
      );
  }
}

export class PlayerOpinion implements IPlayerOpinionInfo {
  id;
  player_id;
  opinionType;
  to;
  constructor(playerOpinion: IPlayerOpinionInfo) {
    this.id = playerOpinion.id;
    this.player_id = playerOpinion.player_id;
    this.opinionType = playerOpinion.opinionType;
    this.to = playerOpinion.to;
    makeAutoObservable(this);
  }
}
export const playersOpinion = new PlayersOpinion();
