import { MultiSelect } from "react-multi-select-component";
import { observer } from "mobx-react-lite";
import { IMultiSelectOption } from "../constructor/opinion/PlayersOpinionMultiSelect";
import { IAnswer } from "../../store/classes/answers/IAnswer";
import { useEffect, useState } from "react";
interface IAnswerComp {
  key: any;
  listOfOptions: IMultiSelectOption[];
  answer: IAnswer;
  onChange: (answer: IAnswer) => any;
  className: string;
}

const ListOfAnswersRect = ({
  listOfOptions,
  onChange,
  answer,
}: Pick<IAnswerComp, "listOfOptions" | "answer" | "onChange">) => {
  const [listOfSelected, setListOfSelected] = useState<IMultiSelectOption[]>(
    [],
  );

  const onClick = (option: IMultiSelectOption) => {
    const hasOptionInAr = listOfSelected.filter((e) => {
      return e.value == option.value;
    }).length;
    if (hasOptionInAr) {
      const newAr = [...listOfSelected.filter((e) => e.value != option.value)];
      setListOfSelected(newAr);

      onChange({
        ...answer,
        ...{
          data: newAr,
        },
      });
    } else {
      const newAr = [...listOfSelected, ...[option]];
      setListOfSelected(newAr);
      onChange({
        ...answer,
        ...{
          data: newAr,
        },
      });
    }
  };

  return (
    <div className="d-flex">
      {/* {listOfSelected.map((e) => e.value).join(",")} */}
      {listOfOptions.map((option) => {
        const isSelected = listOfSelected.filter((selected) => {
          return selected.value == option.value;
        }).length;

        return (
          <div
            onClick={() => onClick(option)}
            className={
              "me-2 mt-1 answer-button " +
              (isSelected ? "answer-button-active" : "answer-button-passive")
            }
          >
            {option.value}
          </div>
        );
      })}
    </div>
  );
};

export const Answer = observer(
  ({ listOfOptions, answer, onChange, className }: IAnswerComp) => {
    const [localAnswer, setLocalAnswer] = useState({
      ...JSON.parse(JSON.stringify(answer)),
    });
    const onSelectChange = (selected) => {
      setLocalAnswer({ ...answer, ...{ data: selected } });
      onChange({ ...answer, ...{ data: selected } });
    };
    return (
      <div className={"card mb-2 " + className}>
        <div className="card-header">{answer.questionText}</div>
        <div className="card-body">
          {/* <MultiSelect
            options={listOfOptions}
            value={localAnswer.data}
            labelledBy={"Select"}
            onChange={onSelectChange}
          /> */}
          <ListOfAnswersRect
            key={answer.questionId}
            answer={answer}
            onChange={onChange}
            listOfOptions={listOfOptions}
          ></ListOfAnswersRect>
        </div>
      </div>
    );
  },
);
