import { useStore } from "../../store/store";
import { IMessage } from "../../store/classes/messages/IMessage";
import { observer } from "mobx-react-lite";
import { messages } from "../../store/classes/messages/Messages";

interface IMessageBlock {
  message: IMessage;
}

export const MessageBlock = ({ message }: IMessageBlock) => {
  return (
    <>
      <div className={"alert message-from-server " + message.className}>
        {message.text}
      </div>
    </>
  );
};

interface IListOfMessages {
  areaKey: string;
}
export const ListOfMessages = observer(({ areaKey }: IListOfMessages) => {
  const { games, settings, playersOpinionGl, rounds, players, messagesGl } =
    useStore();
  return (
    <div className="container-fluid">
      {messages.data
        .filter((el) => {
          return el.area === areaKey;
        })
        .map((el) => {
          return <MessageBlock message={el}></MessageBlock>;
        })}
    </div>
  );
});
