import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";
import { sherChecksGl } from "../../../globalConst/sherChecksGl";

export interface ISherChecks {
  pickedPlayerId: string;
}
export const SherChecks = observer(({ pickedPlayerId }: ISherChecks) => {
  const { players, rounds, settings } = useStore();
  return (
    <>
      {players.data[pickedPlayerId].isSher && (
        <>
          <div>Я - шериф! Мои проверки:</div>
          <table className="table">
            <thead>
              <tr>
                <th>Раунд</th>
                <th>Игрок</th>
                <th>Цвет</th>
              </tr>
            </thead>
            <tbody>
              {players.data[pickedPlayerId].sherCheckAr.map((el) => {
                return (
                  <tr key={pickedPlayerId + "_" + el.roundId}>
                    <td>
                      {rounds.getRoundTitle(el.roundId, settings.pickedGameId)}
                    </td>
                    <td>{players.findOrEmpty(el.playerId)?.text}</td>
                    <td>{sherChecksGl[el.playerCheck]}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </>
      )}
    </>
  );
});
