import { BasePage } from "../../BasePage";
import { MainGame } from "./MainGame";
import { useEffect } from "react";
import { gameSettings } from "../../../store/classes/temp/TempSettings";
import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { useLocation } from "react-router";
import { useWindowSize } from "../../../hooks/hooks";

export const MainGamePage = observer(() => {
  const { games, settings, rounds, players, playersOpinionGl } = useStore();
  const location = useLocation();
  const [width, height] = useWindowSize();

  // 300x = 0.8
  // 1500x = 0.5

  //=>
  //1200x = 0.3
  //x = 0.0025
  useEffect(() => {
    const widthRatio = 0.875 - 0.00025 * width;
    gameSettings.init(width * widthRatio);
    settings.pickedGameId = location.pathname.split("/").at(-1);
    settings.screenWidth = width;
    games.initGame(settings.pickedGameId);
  });

  return (
    <BasePage>
      <div>
        {settings.pickedGameId && (
          <MainGame globalGameId={settings.pickedGameId} />
        )}
      </div>
    </BasePage>
  );
});
