import { makeAutoObservable } from "mobx";
import { IUserRegistration } from "./IUserRegistration";
import { queryService } from "../../../services/Query";

export class UserRegistration implements IUserRegistration {
  email: string = "";
  userName: string = "";
  password: string = "";
  repeatedPassword: string = "";

  authEmail: string = "";
  authPassword: string = "";
  constructor() {
    makeAutoObservable(this);
  }
  get user(): IUserRegistration {
    return {
      email: this.email,
      userName: this.userName,
      password: this.password,
      repeatedPassword: this.repeatedPassword,
    };
  }
  async registration() {
    const registrResp = await queryService.noTokenQuery("/emailRegistration", {
      user: {
        email: this.email,
        userName: this.userName,
        password: this.password,
        repeatedPassword: this.repeatedPassword,
      },
    });
    return registrResp;
  }
  async emailAuth() {
    const authResp = await queryService.noTokenQuery("/emailAuth", {
      user: {
        email: this.authEmail,
        password: this.authPassword,
      },
    });
    return authResp;
  }
}
export const userReg = new UserRegistration();
