import { Link } from "react-router-dom";
import { observer } from "mobx-react-lite";
import { useNavigate } from "react-router";
import { queryService } from "../services/Query";
import { IUserResp } from "../interfaces/IUserResp";
import { Cookies } from "typescript-cookie";
import { serverUrl } from "../env";
import { UserAdminStatuses } from "../common/enums/UserAdminStatuses";
// import { setCookie } from "typescript-cookie/dist/built/src";

export const Header = observer(() => {
  const navigate = useNavigate();

  const mailLogOut = async () => {
    // document.cookie = `mafId=${queryService.mafId}`;
    const logOutRes = await queryService.tokenWithCookieQuery(
      "/exitFromAccount",
      {}
    );
    if (logOutRes.status) {
      queryService.currentUser = {} as IUserResp;
      queryService.refreshToken = "";
      queryService.accessToken = "";
    }
    navigate("/tgAuth");
    // document.location.reload();
  };

  const initNewGame = async (e) => {
    // e.preventDefault();
    // globalInit();
    navigate("/games/new/");
  };

  return (
    <header>
      <nav
        className="navbar navbar-expand-lg navbar-light bg-light"
        style={{ padding: 0 + "px" }}
      >
        <div className="container-fluid" style={{ background: "#fff" }}>
          <Link key="logo" to="/list" className="navbar-brand">
            <img
              style={{ width: 50 + "px", height: 50 + "px" }}
              src="/logo.svg"
            />
          </Link>
          <button
            className="navbar-toggler"
            type="button"
            data-bs-toggle="collapse"
            data-bs-target="#navbarNav"
            aria-controls="navbarNav"
            aria-expanded="false"
            aria-label="Toggle navigation"
          >
            <span className="navbar-toggler-icon"></span>
          </button>
          {queryService.accessToken && (
            <div className="collapse navbar-collapse" id="navbarNav">
              <ul className="navbar-nav ms-auto">
                <li className="nav-item">
                  <Link key="main" to="/list" className="nav-link">
                    Главная
                  </Link>
                </li>
                <li className="nav-item">
                  <Link key="main" to="/games/finished" className="nav-link">
                    Завершенные
                  </Link>
                </li>
                <li className="nav-item">
                  <Link key="main" to="/games/my" className="nav-link">
                    Мои
                  </Link>
                </li>
                <li className="nav-item">
                  {queryService.currentUser.admin >=
                    UserAdminStatuses.admin && (
                    <button className="btn btn-warning" onClick={initNewGame}>
                      Создать
                    </button>
                  )}
                </li>
                <li className="nav-item">
                  <span onClick={mailLogOut} className="nav-link">
                    Выйти
                  </span>
                </li>
              </ul>
            </div>
          )}
          {!queryService.accessToken && (
            <div className="collapse navbar-collapse" id="navbarNav">
              <ul className="navbar-nav ms-auto">
                <li className="nav-item">
                  <Link key="main" to="/tgAuth" className="nav-link">
                    Авторизация
                  </Link>
                </li>
              </ul>
            </div>
          )}
        </div>
      </nav>
    </header>
  );
});
