import { makeAutoObservable } from "mobx";
import {
  IPlayerInfo,
  ISherCheck,
} from "../../../common/interfaces/player/IPlayerInfo";
import { gameSettings } from "../temp/TempSettings";
import { IStoreObject } from "../../interfaces/IStoreObject";
import { PlayerPositions } from "../../../common/enums/PlayerPositionTypes";
import { playersOpinion } from "../playersOpinion/PlayersOpinion";

export class Players implements IStoreObject<IPlayerInfo> {
  public data: {
    [id: string]: Player;
  } = {};
  constructor() {
    makeAutoObservable(this);
  }
  add(player: IPlayerInfo) {
    this.data[player.id] = new Player(player);
  }
  get playersAr() {
    return Object.keys(this.data).map((key) => this.data[key]);
  }
  findOrEmpty(id: string) {
    return this.data[id] ?? Players.getEmptyPlayer();
  }
  get currentPlayer() {
    return this.data[gameSettings.pickedPlayerId];
  }
  getPlayersByRoundId(roundId: string) {
    return this.playersAr.filter((el) => el.roundId == roundId);
  }
  getPlayersByRoundIdAndOpinion(
    roundId: string,
    opinionType: PlayerPositions,
    playerId: string
  ) {
    const playersIdToDel = playersOpinion
      .getOpinionByPlayerId(playerId)
      .filter((opinion) => {
        return opinion.opinionType !== opinionType;
      })
      .map((opinion) => opinion.to);

    playersIdToDel.push(playerId);

    return this.getPlayersByRoundId(roundId).filter(
      (player) => !playersIdToDel.includes(player.id)
    );
  }
  init(data) {
    Object.keys(data).map((el) => {
      this.add(data[el]);
    });
  }
  initAr(dataAr: IPlayerInfo[]) {
    dataAr.map((el) => {
      this.add(el);
    });
  }
  public static getEmptyPlayer(): IPlayerInfo {
    return {} as IPlayerInfo;
  }
  public delete(playerId: string) {
    delete this.data[playerId];
    playersOpinion.getOpinionByPlayerId(playerId).forEach((opinion) => {
      playersOpinion.delete(opinion.id);
    });
  }
}
export class Player implements IPlayerInfo {
  public id: string;
  public roundId: string;
  public alive: boolean;
  public text: string;
  public numberValue: number;
  public isSher: boolean;
  public sherCheck = {};
  constructor(player: IPlayerInfo) {
    this.id = player.id;
    this.roundId = player.roundId;
    this.alive = player.alive;
    this.text = "Игрок №" + (player.numberValue + 1);
    this.numberValue = player.numberValue;
    this.isSher = player?.isSher ?? false;
    this.sherCheck = player.sherCheck ?? {};
    makeAutoObservable(this);
  }
  get sherCheckAr(): ISherCheck[] {
    return (
      Object.keys(this.sherCheck).map((key) => {
        return this.sherCheck[key];
      }) ?? []
    );
  }
}
export const players = new Players();
