import { makeAutoObservable } from "mobx";
import { IPlayerSetting } from "../../interfaces/IPlayerSetting";
import { IPagination } from "../../../components/pages/list/ListOfGames";

export class TempSettings {
  public newGames: {
    [gameId: string]: string;
  } = {};
  get gameFieldUpdateCounter(): number {
    return this._gameFieldUpdateCounter;
  }

  set gameFieldUpdateCounter(value: number) {
    this._gameFieldUpdateCounter = value;
  }
  get angleDiff(): number {
    return this._angleDiff;
  }

  set angleDiff(value: number) {
    this._angleDiff = value;
  }
  get elementRadius(): number {
    return this._elementRadius;
  }
  get numberOfElements(): number {
    return this._numberOfElements;
  }
  private _pickedGameId: string = "";
  private _pickedRoundId: string = "";
  private _pickedPlayerId: string = "";
  private _pickedPlayerOpinion: string = "";
  public _playerSettings: {
    [id: string]: IPlayerSetting;
  } = {};
  private _radius: number = 0;
  private _angleDiff: number = 0;
  private _elementRadius: number = 0;
  private _numberOfElements: number = 10;
  private _gameFieldUpdateCounter = 0;
  public radiusGrow: number = 2;
  public screenWidth = 0;
  public pickedAnswerId = "";
  public screenGameWidth: number = 0;
  public screenGameHeight: number = 0;
  public screenGamePortraitPrimaryK = 0.2;
  public pickedSettingPlayer: string = "";
  public pagination: IPagination = {} as IPagination;

  get playerSettings() {
    return this._playerSettings;
  }
  get pickedPlayerId(): string {
    return this._pickedPlayerId;
  }

  get playerSettingsAr() {
    return Object.keys(this._playerSettings).map((el) => {
      return this._playerSettings[el];
    });
  }

  public initPagination() {
    this.pagination = {
      hasMore: true,
      count: 6,
      currentPage: 1,
    };
  }

  set playerSettings(value) {
    this._playerSettings = value;
  }

  set pickedPlayerId(value: string) {
    this.gameFieldUpdateCounter++;
    this._pickedPlayerId = value;
    this.pickedPlayerOpinion = "";
  }
  get pickedPlayerOpinion(): string {
    return this._pickedPlayerOpinion;
  }

  set pickedPlayerOpinion(value: string) {
    this._pickedPlayerOpinion = value;
  }

  get pickedRoundId(): string {
    return this._pickedRoundId;
  }
  set pickedRoundId(value: string) {
    this._pickedRoundId = value;
    this.pickedPlayerId = "";
    this.pickedSettingPlayer = "";
  }

  get pickedGameId(): string {
    return this._pickedGameId;
  }
  set pickedGameId(value: string) {
    if (this._pickedGameId != "" && this._pickedGameId !== value) {
      this.pickedRoundId = "";
    }
    this._pickedGameId = value;
  }
  constructor() {
    makeAutoObservable(this);
  }
  init(parentWidth: number) {
    this._radius = parentWidth / 3.8;
    this._angleDiff = (2 * Math.PI) / this._numberOfElements;
    this._elementRadius = this._radius / (this._numberOfElements * 0.4);
    let currentAngel = 0;
    for (let i = 0; i < this._numberOfElements; i++) {
      //начинаем с центра
      let a = this._radius - this._elementRadius;
      let b = this._radius - this._elementRadius;

      a += Math.sin(currentAngel) * this._radius * -1;
      b += Math.cos(currentAngel) * this._radius;

      a = a * 1.4;
      b = b * 1.4;

      a = Math.round(a * 100) / 100;
      b = Math.round(b * 100) / 100;
      let currentPlayerSettings = {
        value: i,
        numberValue: i + 1,
        top: a,
        left: b,
        centerTop: a + this._elementRadius,
        centerLeft: b + this._elementRadius,
      };

      this._playerSettings[i] = {
        ...this._playerSettings[i],
        ...currentPlayerSettings,
      };
      currentAngel += this._angleDiff;
    }
  }
}
export const gameSettings = new TempSettings();
