import { makeAutoObservable } from "mobx";
import { IQuestion } from "../../../interfaces/IQuestion";
import { IMultiSelectOption } from "../../../components/constructor/opinion/PlayersOpinionMultiSelect";
import { uuidv4 } from "../../utils";

export class Questions {
  data: {
    [id: string]: Question;
  } = {};
  constructor() {
    makeAutoObservable(this);
  }
  get dataAr() {
    return Object.keys(this.data).map((el) => {
      return this.data[el];
    });
  }
  add(item: IQuestion) {
    this.data[item.id] = new Question(item);
  }
  get answersAr() {
    return Object.values(this.data);
  }
  getEmpty() {
    return {
      ...({} as IQuestion),
      ...{ id: uuidv4(), answer: [], question: "" },
    };
  }
  findOrEmpty(id: string) {
    return this.data[id] ?? this.getEmpty();
  }
  getByGameId(gameId: string) {
    return this.dataAr.filter((el) => {
      return el.gameId === gameId;
    });
  }
  onSave(gameId: string) {
    return this.getByGameId(gameId).reduce((prev, curr) => {
      return { [curr.id]: curr, ...prev };
    }, {});
  }
  delete(id: string) {
    delete this.data[id];
  }
}
export class Question implements IQuestion {
  public answer: IMultiSelectOption[];
  public id: string;
  public question: string;
  public gameId: string;
  constructor(item: IQuestion) {
    makeAutoObservable(this);
    this.id = item.id;
    this.answer = item.answer;
    this.question = item.question;
    this.gameId = item.gameId;
  }
}

export const questions = new Questions();
