import { BasePage } from "../../BasePage";
import { useEffect } from "react";
import { gameSettings } from "../../../store/classes/temp/TempSettings";
import { useStore } from "../../../store/store";
import { observer } from "mobx-react-lite";
import { useLocation } from "react-router";
import { useWindowSize } from "../../../hooks/hooks";
import { MainGame } from "../game/MainGame";
import { games } from "../../../store/classes/games/Games";

export const NewGamePage = observer(() => {
  const { games, settings, rounds, players, playersOpinionGl } = useStore();
  const location = useLocation();
  const [width, height] = useWindowSize();

  const loaGame = async () => {
    settings.pickedGameId = games.createEmptyGame();
  };

  // 300x = 0.8
  // 1500x = 0.5

  //=>
  //1200x = 0.3
  //x = 0.0025
  useEffect(() => {
    settings.pickedGameId = games.createEmptyGame();
  }, []);
  useEffect(() => {
    const widthRatio = 0.875 - 0.00025 * width;
    settings.init(width * widthRatio);
    // settings.pickedGameId = location.pathname.split("/").at(-1);
    settings.screenWidth = width;
    settings.newGames[settings.pickedGameId] = settings.pickedGameId;
  }, [settings.pickedGameId]);

  return (
    <BasePage>
      <div>
        {settings.pickedGameId && (
          <MainGame globalGameId={settings.pickedGameId} isNewGame={true} />
        )}
      </div>
    </BasePage>
  );
});
